(window.TZ_CONTENT=window.TZ_CONTENT||{})["ar"]={"taaruf.001": "التعريف بالحركة", "taaruf.002": "هذه حركة إصلاحية غير سياسية، بريئة من التعصب الطائفي، تدعو الناس إلى الشريعة والسنة على طريقة الإمام الرباني مجدد الفِ ثانی رحمه الله، وعلى طريقة مرشديها الكاملين: شمس الکونین خواجہ محمد عبدالخالق نقشبندی، قادری، سہروردی رحمه الله، وشمس العارفین حضرت سائیں عبدالرزاق خالقی نقشبندی رحمه الله، وامام الذاکرین سائیں محمد عظیم اللہ رزاقی نقشبندی رحمه الله.", "taaruf.003": "ليس هنا طمعٌ، ولا رغبةٌ في الشهرة والكثرة، وإنما هو رضا الله وإصلاح القلب والنفس فحسب.", "taaruf.004": "أهداف الحركة", "taaruf.005": "تحریک اتباعِ سنت پاکستان حركة إسلامية غير سياسية، بريئة من التعصب الطائفي، يحقّ لكل فرد من أفراد الأمة الإسلامية أن ينال عضويتها. وأهدافها الأساسية ما يلي:", "taaruf.006": "في هذا العصر المليء بالفتن، حيث بلغت البدع والخرافات ذروتها، غرسُ الرغبة في الأمة الإسلامية في اجتناب البدع والخرافات، وفي تعلّم الشريعة المطهرة وسنة المصطفى ﷺ وتعليمهما والعمل بهما، لنيل خشية الله وعشق المصطفى ﷺ. ويكون ذلك بالإكثار من تنظيم حلقات الدرس والتدريس، مع تبليغ الشريعة والسنة في كل حين وفي الحِلّ والترحال.", "taaruf.007": "إنشاء أكبر عدد ممكن من المدارس الدينية لنشر تعليم الشريعة والسنة والقرآن.", "taaruf.008": "إنشاء دور الأيتام لغرس روح خدمة الخلق وتعزيز كفالة الأيتام.", "taaruf.009": "إبعاد الجيل الناشئ خاصةً عن الفحشاء والمنكر، وجلبه إلى المسجد لأداء الصلوات الخمس جماعةً.", "taaruf.010": "إقامة أكبر عدد ممكن من مجالس ذكر الله وذكر المصطفى ﷺ، للقضاء على البدع التي تقع في الحياة اليومية وفي الأعراس وسائر مناسبات الفرح والحزن، ولنشر الشريعة والسنة.", "taaruf.011": "نشر التعاليم الحقيقية للأولياء الكاملين في ضوء القرآن والسنة، واستئصال التعاليم المختلقة لأدعياء المشيخة والمشعوذين والمتوارثين للمشيخة بالنسب، وبذلك تجديد الوجه المشوَّه للتصوف في هذا الزمان.", "taaruf.012": "نشر الصلاة والسلام ومجالس الذكر والمديح النبوي لنيل المحبة الكاملة للنبي الكريم ﷺ.", "taaruf.013": "القضاء على المفاسد الاجتماعية والأخلاقية، وإشاعة حسن المعاملة والتعاليم الأخلاقية.", "taaruf.014": "غرس الميل لدى النساء إلى الحجاب الشرعي وطاعة أزواجهن بدلاً من الولع بالموضة.", "taaruf.015": "غرس روح المحبة والوفاء للعالم الإسلامي كله، ولا سيما للوطن العزيز باكستان.", "taaruf.016": "تشجيع أداء الصلاة في أول وقتها. ففي هذه الأيام تُؤدّى صلاتا الفجر والظهر في المساجد متأخرتين كثيراً، وهذا تهاونٌ في الصلاة، مع أن الوقت بحسب المواقيت الحنفية يدخل قبل ذلك بكثير.", "taaruf.017": "حماية ناموس الرسالة وختم النبوة، وكشف مؤامرات اليهود والهندوس والقاديانيين.", "taaruf.018": "اتباع الرسول ﷺ", "taaruf.019": "في ضوء القرآن الكريم", "taaruf.020": "يقول الله تعالى في سورة آل عمران: <span class=\"kk-ar\" style=\"display:block\">قُلْ اِنْ كُنْتُمْ تُحِبُّوْنَ اللّٰهَ فَاتَّبِعُوْنِيْ يُحْبِبْكُمُ اللّٰهُ وَيَغْفِرْ لَكُمْ ذُنُوْبَكُمْ</span>والنبي ﷺ حبيب الله تعالى، والمحبّ يتخذ محبوباً له كلَّ من يرى فيه عادات محبوبه وخصاله. فالسعي في اتباعه ﷺ يبلّغ مقام المحبوبية ويمحو الذنوب. فواجب على كل عاقل لبيب أن يسعى في كمال اتباعه ﷺ ظاهراً وباطناً.", "taaruf.021": "وقال في سورة الأحزاب: <span class=\"kk-ar\" style=\"display:block\">لَقَدْ كَانَ لَكُمْ فِيْ رَسُوْلِ اللّٰهِ اُسْوَةٌ حَسَنَةٌ لِّمَنْ كَانَ يَرْجُوا اللّٰهَ وَالْيَوْمَ الْاٰخِرَ وَذَكَرَ اللّٰهَ كَثِيْرًا</span>فمن أناب إلى الله وأراد الاستعداد للآخرة وكان من الذاكرين الله كثيراً، فعليه أن يتبع طريقة النبي الكريم ﷺ المنيرة في كل جانب من جوانب حياته.", "taaruf.022": "وقال في سورة النساء: <span class=\"kk-ar\" style=\"display:block\">مَنْ يُّطِعِ الرَّسُوْلَ فَقَدْ اَطَاعَ اللّٰهَ</span>فعُلم أن الله تعالى جعل طاعته مندرجةً في طاعة حبيبه ﷺ. فطاعة الرسول هي طاعة الله، وذكر الرسول ﷺ هو عين ذكر الله. فمن ظنّ طاعة رسول الله ﷺ منفصلةً عن طاعة الله تعالى فهو منكر للقرآن.", "taaruf.023": "<b>طاعة الرسول ﷺ سبيلٌ إلى رفقة عباد الله المقرَّبين ومعيّتهم:</b> قال الله تعالى في سورة النساء: <span class=\"kk-ar\" style=\"display:block\">وَمَنْ يُّطِعِ اللّٰهَ وَالرَّسُوْلَ فَاُولٰٓئِكَ مَعَ الَّذِيْنَ اَنْعَمَ اللّٰهُ عَلَيْهِمْ مِّنَ النَّبِيّٖنَ وَالصِّدِّيْقِيْنَ وَالشُّهَدَآءِ وَالصّٰلِحِيْنَ ۚ وَحَسُنَ اُولٰٓئِكَ رَفِيْقًا</span>", "taaruf.024": "<b>بغير طاعة رسول الله ﷺ تضيع الأعمال:</b> قال الله تعالى في سورة محمد: <span class=\"kk-ar\" style=\"display:block\">يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوْٓا اَطِيْعُوا اللّٰهَ وَاَطِيْعُوا الرَّسُوْلَ وَلَا تُبْطِلُوْٓا اَعْمَالَكُمْ</span>", "taaruf.025": "<b>طاعة الرسول ﷺ سبيلٌ إلى رحمة الله:</b> وفي سورة آل عمران: <span class=\"kk-ar\" style=\"display:block\">وَاَطِيْعُوا اللّٰهَ وَالرَّسُوْلَ لَعَلَّكُمْ تُرْحَمُوْنَ</span>", "taaruf.026": "<b>طاعة الرسول ﷺ سببُ الفلاح في الدارين:</b> <span class=\"kk-ar\" style=\"display:block\">وَمَنْ يُّطِعِ اللّٰهَ وَرَسُوْلَهٗ فَقَدْ فَازَ فَوْزًا عَظِيْمًا</span>(سورة الأحزاب)", "taaruf.027": "وبيّن في الآية ٥١ من سورة النور صفة المؤمنين المفلحين: (﴿إِنَّمَا كَانَ قَوْلَ الْمُؤْمِنِينَ إِذَا دُعُوا إِلَى اللَّهِ وَرَسُولِهِ لِيَحْكُمَ بَيْنَهُمْ أَن يَقُولُوا سَمِعْنَا وَأَطَعْنَا ۚ وَأُولَٰئِكَ هُمُ الْمُفْلِحُونَ﴾). وقال في الآية التالية: <span class=\"kk-ar\" style=\"display:block\">وَمَنْ يُّطِعِ اللّٰهَ وَرَسُوْلَهٗ وَيَخْشَ اللّٰهَ وَيَتَّقْهِ فَاُولٰٓئِكَ هُمُ الْفَآئِزُوْنَ</span>وفي تفسير هذه الآية قال سيدنا عمر رضي الله عنه: إن من أطاع الله تعالى في الفرائض، واتبع رسول الله ﷺ في السنن، وخشي الله تعالى لما سلف من خطاياه، واتقى معصية الله فيما بقي من عمره، فأولئك هم الفائزون؛ والفائز من زُحزح عن النار وأُدخل الجنة. (ضیاء القرآن)", "taaruf.028": "وقال في سورة الأنفال: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا اسْتَجِيبُوا لِلَّهِ وَلِلرَّسُولِ إِذَا دَعَاكُمْ لِمَا يُحْيِيكُمْ﴾ (٢٤). فدعوة النبي ﷺ هي دعوة الله تعالى.", "taaruf.029": "وقال الله تعالى في سورة الحشر: ﴿وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانتَهُوا ۚ وَاتَّقُوا اللَّهَ﴾ (٧). فعُلم من هذه الآية الكريمة أن طاعته ﷺ، أي العمل بأحكام الله والانتهاء عن المنكرات، واجبة، وأن الله يعذّب عذاباً شديداً من عصاه ﷺ.", "taaruf.030": "في ضوء الأحاديث الشريفة", "taaruf.031": "<span class=\"kk-ar\" style=\"display:block\">خَيْرُ الْهُدٰى هُدٰى مُحَمَّدٍ ﷺ</span>خيرُ الطريق طريقُ سيدنا محمد ﷺ. (البخاري)", "taaruf.032": "قال المصطفى ﷺ ما معناه: من أعرض عن سنتي أو تركها عمداً فليس منا، ولا يستحق الشفاعة يوم القيامة. ومن أحبّ سنتي فقد أحبني، ومن أحبني كان معي في الجنة. (الترمذي)", "taaruf.033": "كل أمتي يدخلون الجنة إلا من أبى (فإنه لا يدخل الجنة). ولما سُئل قال: من عصاني فقد أبى. ويشهد لذلك القرآن: ﴿وَيَوْمَ يَعَضُّ الظَّالِمُ عَلَىٰ يَدَيْهِ يَقُولُ يَا لَيْتَنِي اتَّخَذْتُ مَعَ الرَّسُولِ سَبِيلًا ۝ يَا وَيْلَتَىٰ لَيْتَنِي لَمْ أَتَّخِذْ فُلَانًا خَلِيلًا﴾ (سورة الفرقان: ٢٧)", "taaruf.034": "دعا النبي الكريم ﷺ قائلاً: رحمة الله على خلفائي. فقيل: ومن خلفاؤك؟ قال: الذين يحبّون سنتي ويعلّمونها عبادَ الله. (جامع بيان العلم وفضله)", "taaruf.035": "وقال ﷺ قبل وفاته: تركتُ فيكم أمرين لن تضلّوا ما تمسكتم بهما: كتاب الله، وسنة رسول الله ﷺ. (البخاري، كتاب الأحكام)", "taaruf.036": "في ضوء أقوال الأكابر", "taaruf.037": "<b>ثانيَ اثنين سيدنا الصديق الأكبر رضي الله عنه:</b> قال في خطبته التاريخية بعد أن صار الخليفة الأول: أطيعوني ما أطعتُ الله تعالى ورسوله ﷺ، فإن خالفتُهما فاتركوني. وكان رضي الله عنه شديد الشوق إلى اتباع الرسول ﷺ، ويُدرَك ذلك من الحديث الذي دار بينه وبين ابنته الحبيبة أم المؤمنين السيدة عائشة الصديقة رضي الله عنها قبل وفاته المباركة بساعات. قال: يا عائشة، في كم ثوبٍ كفّنتم رسول الله ﷺ؟ قالت: في ثلاثة أثواب بيض ليس فيها قميص ولا عمامة. قال: في أي يوم توفي رسول الله ﷺ؟ قالت: يوم الاثنين. قال: فأي يوم هذا؟ قالت: الاثنين. قال: أرجو أن تكون وفاتي فيما بين هذه الساعة والليل. فكان كذلك بفضل الله، إذ أكرمه الله رب العزة بشرف اتباع الرسول ﷺ حتى عند وفاته، فتوفي رضي الله عنه يوم الاثنين عن ثلاث وستين سنة من عمره المبارك. وكان يقول: لا أترك شيئاً كان رسول الله ﷺ يعمل به إلا عملتُ به، فإني أخشى إن تركتُ شيئاً من أمره ﷺ أن أزيغ عن سنة الرسول ﷺ.", "taaruf.038": "<b>سلطان العارفین حضرت بایزید بسطامی رحمه الله:</b> بلغه عن رجل أنه لم يزل قائمَ الليل صائمَ النهار، فقال: لقد اكتسب بالمجاهدة صفات الملائكة، ولكن هذا ليس مقاماً ولا هو ولاية؛ بل كمال الولاية أن يكتسب المرء الصفات المحمدية ﷺ، أي أن يجعل جميع أوقات حياته، في قيامه وصيامه وكلامه وطعامه، موافقةً لسنة المصطفى ﷺ. وطريق الشريعة أدقّ وأخطر من الصراط، فلا ينبغي في أي حال أن يخطو المرء خارج حدود الشريعة.", "taaruf.039": "<b>سید الطائفہ شیخ جنید بغدادی رحمه الله:</b> يقول: لا يستطيع اتباع الشريعة إلا من كان القرآن الكريم في يمينه وسنة المصطفى ﷺ في شماله، فيسلك الطريق في ضوء هذين السراجين، حتى لا يقع في حُفَر الشبهة ولا يتيه في ظلمات البدعة.", "taaruf.040": "<b>غوثِ زماں شیخ ابوالقاسم گرگانی رحمه الله:</b> يقول: إن المشي على سطح الماء، والطيران في الهواء، ومعرفة المغيَّبات والإخبار بها، لا يصحّ أن يُسمّى شيءٌ منها كرامة، لأن ذلك كله ممكن بعون الشيطان أيضاً، بل كم من كاهنٍ يخبر بالمغيّبات. وإنما أعظم الكرامات أن يصير المرء كلُّه امتثالاً لأمر الله، وأن ينقاد للشريعة بجسده وقلبه وماله، فلا يُرى في فعل من أفعاله أو حركة من حركاته أدنى شائبة لمخالفة أحكام الشريعة. فإن كانت هذه حاله فهو أهلٌ للثقة. وإن لم تستطع في متابعة الشريعة أن تركب الأسد فلا بأس، فإن قهر ذلك الكلب، كلب الغضب والسخط، أي النفس القابعة في صدرك، أفضل بدرجات من ركوب أسود كثيرة. ومعرفة مكر النفس وخداعها هي أعظم علم بالغيب. والخروج من دائرة الحسّ والخيال ليس بأقلّ من المشي على الماء والطيران في الهواء. وأن تتجاوز طمع الدنيا وشواغلها مستغنياً عنها، وأن تردّ درهماً مشتبهاً، أي مشكوكاً فيه، ليس بأقلّ من قطع ميادين واسعة وغابات وعبور عقبة وعرة؛ فقد سمّى الحق تعالى هذه العوائق في كلامه المجيد عقبات.", "taaruf.041": "<b>حضرت داتا گنج بخش ہجویری رحمه الله:</b> يقرّر أن اتباع الشريعة لازم للترقي الروحي، فيقول: الركن الأول في الشريعة الكتاب، كما يقول الله تعالى: ﴿مِنْهُ آيَاتٌ مُّحْكَمَاتٌ هُنَّ أُمُّ الْكِتَابِ﴾ (سورة آل عمران: ٧). والركن الثاني سنة الرسول ﷺ ومصدرها الأحاديث، كما في القرآن الكريم: ﴿وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانتَهُوا﴾ (سورة الحشر). والركن الثالث إجماع الأمة، إذ قال رسول الله ﷺ: لا تجتمع أمتي على ضلالة، فالزموا السواد الأعظم. ومن هذا يتضح جواز التقليد أيضاً. ولا يستطيع صوفيٌّ أن يفرّق بين الشريعة والحقيقة؛ فالتعاليم الصوفية تابعة تماماً لأحكام الشريعة. فالطريقة في حقيقتها هي أن يجد المرء الشريعة نفسها في أعماق حياته.", "taaruf.042": "<b>غوث الاعظم محی الدین شیخ عبدالقادر جیلانی رحمه الله:</b> قال: ادخل الظلمة ومعك السراج، وذلك السراج هو كتاب الله وسنة النبي الكريم ﷺ المباركة. لا تخرج أبداً عن أحكام الكتاب والسنة. فإن خطر في قلبك خاطرٌ كالزنا والربا ومخالطة أهل الفسق والفجور ونحو ذلك، أو وقع لك إلهام، فاعرضه على الكتاب والسنة؛ فإن وجدت تحريمه في الكتاب والسنة فلا تقبله واعتزله، وأيقن أنه من الشيطان الرجيم. والعبد بحفظه لحدود الشرع يصير كالعبد المملوك الذي يفوّض إليه سيده جميع الأمور. (فتوح الغيب)", "taaruf.043": "<b>شیخ الشیوخ شیخ شہاب الدین عمر سہروردی رحمه الله:</b> مؤسس الطريقة السهروردية، ومرشد حضرت بہاؤالدین زکریا رحمه الله، يقول في كتابه «عوارف المعارف»: قال رسول الله ﷺ ما معناه: والذي نفسي بيده، إن أحبّ الناس إلى الله هم الذين يوقظون في عباده محبة الله ويسعون في أن يجعلوهم محبوبين لله، بل يسعون في النصح والخير لكل إنسان على وجه الأرض. وفي هذا الحديث بيانُ أوصاف المشايخ الكرام؛ فالشيخ ينوب عن الأنبياء في الدعوة إلى الله، فيغرس محبة الله في مريده بأن يسلك به سبيل اتباع رسول الله ﷺ والاقتداء به، ويسير به في طريق تزكية النفس. فمن اتبع رسول الله ﷺ اتباعاً صحيحاً أحبّه الله تعالى.", "taaruf.044": "<b>امام الطریقت خواجۂ خواجگان سید محمد بہاؤالدین نقشبند رحمه الله:</b> أساس طريقتنا على متابعة الأحاديث والآثار، ومقصودنا أن يكون سلوكنا على اتباع سنة الرسول ﷺ وأن يتميز به الحق من الباطل. وخاصّة الله هم الذين يتبعون الشريعة المطهرة ويقضون حياتهم على مذهب أهل السنة والجماعة. ولو انحنى ظهرك في الرياضة حتى صار بدنك كالقوس، ونجحت في الرياضة أيضاً، فلن تبلغ الغاية المقصودة ما لم تطهّر لقمتك ولباسك وتتبع شريعة الرسول ﷺ. فمدار الأمور كلها على هذا. (أنيس الطالبين)", "taaruf.045": "<b>امامِ ربانی محبوبِ سبحانی حضرت مجدد الف ثانی رحمه الله:</b> يقول: للشريعة ثلاثة أجزاء: العلم والعمل والإخلاص، وما لم تتحقق هذه الأجزاء الثلاثة لا تحصل الشريعة. فإذا حصلت الشريعة فكأنما حصل رضا الحق تعالى، كما قال الله تعالى: (﴿وَرِضْوَانٌ مِّنَ اللَّهِ أَكْبَرُ﴾). فلا يبقى مطلبٌ يُحتاج في تحصيله إلى شيء سوى الشريعة. والطريقة والحقيقة اللتان يمتاز بهما الصوفية خادمتان للشريعة في تكميل جزئها الثالث وهو الإخلاص؛ فالمقصود من تكميلهما تكميل الشريعة، لا أمرٌ آخر سواها. فترك الكذب باللسان شريعة، ونفي خاطر الكذب عن القلب، أي حصول عادة الصدق بلا تكلّف ولا تصنّع، حقيقةٌ أي تصوف. فالتصوف مكمّلٌ للشريعة لا مخالفٌ لها. والعلوم والمعارف التي تحصل للصوفية في هذا الطريق ليست هي المقصود الأصلي، بل هي أوهام وخيالات يُربّى بها أطفال الطريقة. وينبغي تجاوزها كلها والوصول إلى مقام الرضا، فإنه أعلى مقامات الجذبة والسلوك. والجاهلون يحسبون هذه التجليات والمشاهدات هي المقصود الأصلي فيُحرمون كمالات الشريعة. نعم، إن الوصول إلى مقام الإخلاص ومرتبة الرضا متوقفٌ على قطع هذه الأحوال وتحصيل العلوم والمعارف؛ فهذه الأحوال والمعارف أسبابٌ ووسائل لتحصيل المطلوب الأصلي. والشريعة ليست تابعة للأحوال، بل الأحوال الباطنة تابعة للشريعة، لأن الشريعة قطعية ثابتة بالوحي، والأحوال ظنية ثابتة بالكشف والإلهام. فالجماعة التي أوصلها الحق تعالى إلى نهاية النهاية باتباعه ﷺ لا تخالف الشريعة قيدَ شعرة في العلم والعمل، والعلوم اللدنية التي ترد عليهم موافقة للشريعة، بل هي تفصيلٌ للعلوم الشرعية. وكل كشفٍ يخالف ظاهر الشريعة غير مقبول، لأنه حائدٌ عن طريقه ﷺ. قال الله تعالى في سورة يس: (﴿إِنَّكَ لَمِنَ الْمُرْسَلِينَ ۝ عَلَىٰ صِرَاطٍ مُّسْتَقِيمٍ﴾). والعجب أن بعض الناقصين يعتدّون بكشفهم الخيالي ويسعون في مخالفة الشريعة الغراء وإنكارها، مع أن سيدنا موسى عليه السلام، على ما له من مقام الكليم والقرب الخاص، لو كان في الدنيا لاتبع هذه الشريعة المطهرة.", "taaruf.046": "وفي سورة البقرة: ﴿وَالَّذِينَ آمَنُوا أَشَدُّ حُبًّا لِّلَّهِ﴾ (١٦٥). فالتوفيق لأداء الأحكام الشرعية ثمرةُ محبة الله، وحصول الجمعية الباطنة ثمرةُ هذه المحبة. فلو أُلقيت في الباطن ظلماتٌ وكدورات بقدر العالم كله، مع بقاء هذه المحبة، فلا ينبغي الحزن؛ ولو زيدت في الباطن أنوارٌ وكيفيات بقدر الجبال كلها، مع نقص هذه المحبة قيدَ شعرة، فلا ينبغي أن يُعدّ ذلك إلا خراباً. والفرق بين الصادق والكاذب يُعرف بالاستقامة على الشريعة أو عدمها؛ فالصادق لا يخالف الشرع قيدَ شعرة مع ما هو فيه من السكر والوجد والغيبة عن النفس. وكان مولانا روم رحمه الله يكون مستغرقاً، فإذا حان وقت الصلاة أفاق.", "taaruf.047": "قال رسول الله ﷺ: لا يؤمن أحدكم حتى يكون هواه تبعاً لما جئتُ به. فالحكمة في التكاليف الشرعية هي إذلال النفس الأمّارة وإعجازها؛ فبقدر ما يُعمل بموافقة الشريعة تقلّ الأهواء النفسانية. ولهذا كان أداء حكمٍ واحد من الأحكام الشرعية أفضل بدرجات في إزالة الأهواء النفسانية من رياضات ومجاهدات ألف سنة يأتي بها المرء من عند نفسه، بل إن الرياضات والمجاهدات غير الموافقة للشرع معينةٌ للأهواء النفسانية ومقوّية لها. فالبراهمة والجوكية لم يستفيدوا من مشاقّهم ومجاهداتهم إلا تقوية النفس وتربيتها. فمثلاً أداء ركعتي صلاة الفجر جماعةً، وهو سنة من السنن، أفضل بدرجات من قيام الليل كله ثم أداء صلاة الفجر بلا جماعة؛ والأكل يوم عيد الفطر امتثالاً لحكم الشريعة خيرٌ من صيام سنين كثيرة بحسب الهوى؛ وإنفاق روبيةٍ واحدةٍ زكاةً لإذلال النفس خيرٌ من إنفاق ألف روبية بالاختيار الشخصي. والحاصل أنه ما لم تصفُ النفس وتطهر من نجاسة حبّ الرئاسة فالنجاة عسيرة، والخطر قائم من الوصول إلى الموت الدائم.", "taaruf.048": "ذرةٌ من المتابعة المرضية خيرٌ بدرجات من جميع لذات الدنيا ونعيم الآخرة. والفضل منوطٌ باتباع السنة، والزيادة منوطةٌ بامتثال الشريعة. وكل ما خالف الشريعة فهو مردود، وكل حقيقة ردّتها الشريعة فهي زندقة. وطلب الحقيقة مع إبقاء الشريعة في موضعها عملُ الأبطال. والقليل من العمل بعد التصديق بحقيقة دين النبي ﷺ يعدل العمل الكثير. فقد نال أصحاب الكهف تلك الدرجة العظيمة بحسنة واحدة فقط، وهي هجرتهم بنور الإيمان عند غلبة أعداء الله تعالى؛ فإن أدنى سعي عند غلبة الأعداء يكون ظاهراً معتبراً إلى حدٍّ لا يُعتبر معه أضعافه من العمل في أيام الأمن. فإن لم تتيسر الهجرة الظاهرة فينبغي، مراعاةً للهجرة الباطنة، أن يعيش المرء بين الخلق منعزلاً عنهم. ويوم الحشر يُسأل عن الشريعة لا عن التصوف. ودخول الجنة والنجاة من النار منوطان بأداء أحكام الشريعة. والمقصود من بعثة الأنبياء الكرام إنما هو إبلاغ أحكام الشريعة إلى الناس. فأعظم الحسنات وأثقلها هو السعي في ترويج الشرع وإحياء حكمٍ من أحكامه، ولا سيما في زمانٍ انمحت فيه معالم الإسلام تماماً. ومن تعلّقت به نجاة كثير من الناس خيرٌ ممن لا يهمّه إلا نجاة نفسه.", "taaruf.049": "قال الله تعالى: (﴿وَأَنَّ هَٰذَا صِرَاطِي مُسْتَقِيمًا فَاتَّبِعُوهُ ۖ وَلَا تَتَّبِعُوا السُّبُلَ﴾). وقال رسول الله ﷺ: أدّبني ربي فأحسن تعليمي وتأديبي. فإن صدرت من السالكين في طريق الطريقة والحقيقة أثناء سيرهم أمورٌ تخالف الشريعة في الظاهر، فهي ناشئة عن غلبة الحال أي السُّكر، فإذا تجاوزوا هذا المقام وأفاقوا زالت تلك المخالفة. والأكابر ذوو المشرب المحمدي مشرَّفون بنعمة الشرع والسنة، ولهم نصيبٌ من الولاية الخاصة المحمدية ﷺ، والفناء الأتمّ والبقاء الأكمل من شأنهم. ومن خالف ذلك، وإن كان من الأولياء وكان له كشف، فليس له نصيبٌ في هذه الولاية، وإنما هو على قدم نبيٍّ من الأنبياء السابقين، وعلومه موافقة لشريعة ذلك النبي. والشريعة المحمدية ﷺ خلاصة سائر الشرائع، والوصول إلى هذه المنزلة بغير اتباع الشريعة والسنة محال. فطوبى لمن نال شرف هذه النعمة العظيمة، ويا أسفى على من حُرم هذه النعمة العليا.", "taaruf.050": "شكرُ ميراثه ﷺ الظاهر أن يتحلّى المرء بالميراث الباطن، والتحلّي بالميراث الباطن مستحيلٌ بغير اتباعه ﷺ اتباعاً كاملاً. وعلامة كمال محبته ﷺ أن يُبغَض أعداؤه ﷺ وتُظهَر العداوة لمخالفي الشريعة. ولا تجوز المداهنة في المحبة، لأن المحبّ مجنونٌ بمحبوبه، ولا تجتمع محبّتان متضادتان. فيلزم أن يُصرف الهمّ كلّه في أداء الأحكام الشرعية، وفي تعظيم أهل الشريعة من العلماء والأولياء، وفي إذلال المبتدعة. فمن عظّم مبتدعاً فكأنما أعانه على هدم الإسلام. أسأل الحق تعالى، بطفيل نبيه ﷺ، أن يزيّن ظاهرنا وباطننا بمتابعة سنة الرسول ﷺ. (مكتوبات الإمام الرباني مجدد الف ثانی رحمه الله)", "taaruf.051": "مناشداتنا", "taaruf.052": "روح حبّ الوطن", "taaruf.053": "قال النبي الكريم الرؤوف الرحيم ﷺ: حبّ الوطن من الإيمان. (الحديث)", "taaruf.054": "فعلينا أن نسعى ليلاً ونهاراً لإعلاء دين الإسلام ولتثبيت وطننا العزيز باكستان، وأن نغرس في قلوب أبنائنا روح حبّ الوطن إلى جانب خشية الله وعشق المصطفى ﷺ. وخير سبيل إلى ذلك أن تُذكر سِيَر أسلافنا مع ذكر الله تعالى والنبي الكريم ﷺ حتى في مناسبة عيد الاستقلال. وليجعل كلُّ من يؤدي واجباته في أي دائرة الصدقَ والأمانة شعاراً له، حتى إن الرجال والنساء المقيمين في البيوت ينبغي أن يؤدوا مسؤولياتهم على أحسن وجه. ولإصلاح مجتمعنا، فلنرعَ جيراننا ومن حولنا من المساكين والفقراء، ولنعش فيما بيننا بالمودة والمحبة والوفاق والاتحاد وحسن المعاملة. فالمسلم الصالح وحده يمكن أن يكون إنساناً صالحاً وباكستانياً صالحاً.", "taaruf.055": "السفور والاستعمال السلبي للهواتف المحمولة، وسُبُل التصدي لهما", "taaruf.056": "قال الله تعالى في سورة النور: ﴿وَقُل لِّلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ وَلَا يُبْدِينَ زِينَتَهُنَّ﴾ (٣١). وقال: ﴿وَقَرْنَ فِي بُيُوتِكُنَّ وَلَا تَبَرَّجْنَ تَبَرُّجَ الْجَاهِلِيَّةِ الْأُولَىٰ﴾ (سورة الأحزاب). وقال: ﴿حُورٌ مَّقْصُورَاتٌ فِي الْخِيَامِ﴾ (سورة الرحمن: ٧٢). فحتى الحور في الجنة يحتجبن، حيث لا خشية هناك من أي سوء. والحجاب في الحقيقة هو حياء المرأة وجمالها.", "taaruf.057": "اليوم، في هذا العصر المليء بالفتن، حيث بلغ السفور وقلّة الحياء ذروتهما، علينا أن نتعاون على القضاء على عادة السفور القبيحة صوناً لعفاف بناتنا الطاهرات، وأن نرغّب زوجات أبنائنا وبناتنا في الحجاب الشرعي. تقول نساء اليوم المتحرّرات إن الحجاب إنما هو حجاب النظر. فإذا كانت الصحابيات قد احتجبن من النبي الكريم ﷺ، وأمر الله تعالى في كلامه الطاهر بالاحتجاب من كل أجنبي غير مَحْرم، فأيّ قيمة تبقى لهذا التحرّر المعاصر؟", "taaruf.058": "وفضلاً عن ذلك، علينا أن نحمي أبناءنا قدر المستطاع من الاستعمال السلبي للهواتف المحمولة. فقد جاء اليوم ذلك الزمان الذي قال عنه النبي ﷺ إن الفتن ستكسر أبواب البيوت وتدخلها. والهاتف المحمول والتلفاز هما تلك الفتنة التي صار بها وصول الفحش والشر إلى الأطفال وهم في بيوتهم ممكناً. واليوم لا يُرى في حالات واتساب ووسائل التواصل الاجتماعي إلا الرقص والغناء واللهو واللعب. فبالله عليكم! قوا أنفسكم وأهليكم ناراً وقودها الناس والحجارة.", "taaruf.059": "كيف يمكنكم أن تكونوا عوناً لنا في هذا العمل الخيري", "taaruf.060": "إن كنتم متفقين مع أغراض حركتنا هذه ومقاصدها، فبإمكانكم الانضمام إلى عضويتها بالتواصل مع عاملينا المعيَّنين والحصول منهم على استمارة العضوية ومظروف البريد مجاناً تماماً.", "taaruf.061": "وإن كنتم لا تريدون أن تصبحوا أعضاء رسميين، فساندونا في نشر هذه الحركة بالسعي، فرادى أو جماعات، قدر استطاعتكم، في تنفيذ المناشدات المدوّنة في هذا الكتيّب.", "taaruf.062": "المصدر: كتيّب «تحریک اتباعِ سنت پاکستان کا تعارف اور اس کے مقاصد» (تعريف تحریک اتباعِ سنت پاکستان ومقاصدها)", "baani.001": "التعريف بالمؤسس والقائد", "baani.002": "مؤسس حركة اتباع السنة باكستان", "baani.004": "النشأة والتعليم", "baani.005": "مؤسس تحریک اتباعِ سنت پاکستان وقائدها، شيخ الطريقة کرامت علی بن محمد الیاس رزاقی، ينتمي إلى گوٹھ محمد ابڑو بإقليم السند. وهو من حيث النسب من قوم الراجبوت. وبعد التعليم الابتدائي نال درجة البكالوريوس في التجارة (B.Com) من ٹنڈو آدم نیو علی گڑھ کالج في الفترة 1983-84م، ثم نال أثناء عمله درجة الماجستير في الاقتصاد ثم البكالوريوس في القانون (LLB).", "baani.006": "الوظيفة", "baani.007": "في عام 1985م التحق بهيئة بريد باكستان كاتباً أول. وفي عام 2013م، وهو في منصب مساعد مشرف الخدمات البريدية، تقاعد بأمر شيخه قبل موعد التقاعد المقرر بعشر سنوات، وانشغل ليلاً ونهاراً بنشر السلسلة العالية.", "baani.008": "البيعة والخلافة", "baani.009": "لكونه من أسرة متدينة كان ميّالاً إلى الدين منذ البداية، واقتداءً بأكابر أسرته بايع في عام 1981م على يد الشخصية الروحية العظيمة في السلسلة العالية النقشبندية قطبِ عالم حضرت سائیں عبدالرزاق رحمه الله. وكان آنذاك طالباً في الكلية، لكنه كان يضع القلنسوة على رأسه دائماً ويحرص حرصاً خاصاً على المواظبة على الصلوات. ثم قضى مدة طويلة متقطعة في خدمة شيخه ومرشده امام الذاکرین حضور محمد عظیم اللہ رزاقی نقشبندی رحمه الله، وانتفع بصحبته المباركة. وفي نوفمبر 2006م شرّفه شيخه ومرشده بخلافته ونيابته.", "baani.010": "الخدمات الدينية", "baani.011": "يقيم كل عام العرس المبارك على نطاق واسع. ومن منهجه الإكثار من التواصل مع إخوانه في الطريقة، وتبليغ الدين بالوعظ، وعقد مجالس ذكر الحبيب ﷺ. ويستعمل وسائل التواصل الاجتماعي استعمالاً إيجابياً لإيصال رسالة الدين والسلسلة، ويرتّب بثّاً مباشراً عبر الإنترنت ولا سيما في ذكرى وفاة الخلفاء الراشدين وأهل البيت الأطهار وأكابر الدين. وفي إطار هذه الرسالة يسافر باستمرار إلى مختلف مناطق باكستان.", "baani.012": "ويتولى كذلك إدارة مدرسہ عربیہ خالقیہ رزاقیہ القائمة في قريته منذ عام 1972م. وفضلاً عن ذلك شيّد في قريته دانش کدۂ عظیم مرکزِ علم و عرفان، الذي يضم المكتب المركزي لـتحریک اتباعِ سنت پاکستان، ومكتبة مجدد الفِ ثانی رحمه الله، ومسجد سیدنا صدیقِ اکبر رضي الله عنه قيد الإنشاء، ومدرسةً ودارَ أيتام لتعليم الأطفال الأيتام والمحتاجين تعليماً دينياً وعصرياً وكفالتهم. كما أقام مدرسة مستقلة للنساء. ويحثّ إخوانه الآخرين في الطريقة على إنشاء المدارس إلى جانب تنظيم مجالس الذكر والمديح النبوي.", "baani.013": "منهج التربية", "baani.014": "بعيداً عن المشيخة التقليدية، ووفقاً تماماً لطريقة مرشديه الكاملين، يعلّم مريديه وكلَّ من يأتيه دائماً التوحيدَ وخشيةَ الله والتوكلَ على الله ومحبةَ النبي الكريم ﷺ واتباعَه. ويهتم اهتماماً خاصاً بالتعليم العصري إلى جانب إنشاء المدارس والتعليم الديني. ويوصي بقراءة مؤلفات أولئك المشايخ الأجلّاء أنفسهم بدلاً من الكتب القائمة على كشوف المشايخ العظام وكراماتهم، التي لا تخلو يقيناً من قدر كبير من المبالغة.", "baani.015": "المؤلفات", "baani.016": "ألّف وصنّف أكثر من عشرة كتب في الشريعة والطريقة لتنمية الذوق العلمي في السلسلة العالية. ونشر مجموعة من نعوته ومناقبه بعنوان «حروفِ ثناء». ولا يزال يسعى ليلاً ونهاراً لمزيد من النهوض بهذه السلسلة.", "baani.017": "كتابة: انجینئر شعیب عالم عظیمی مجددی", "baani.018": "التعريف بالأنجال", "baani.019": "صاحبزادہ اویس العظیم عظیمی", "baani.020": "تخرّج في جامعة السند، ويعمل حالياً مشغّلاً لاسلكياً في شرطة السند. يحضر المجالس ويتولى عرافتها بأسلوب حماسي جداً.", "murshideen.001": "التعريف بالمرشدين الكاملين", "murshideen.002": "شمس الکونین خواجہ محمد عبدالخالق نقشبندی رحمه الله<span class=\"mk-hint\">اقرأ التعريف ▾</span>", "murshideen.003": "أنيس الأرامل، وكافل اليتامى، وقاهر القاديانية<br>شمس الکونین خواجہ محمد عبدالخالق شمس العرفانی نقشبندی رحمه الله", "murshideen.004": "النشأة", "murshideen.005": "هو نجل شمس العرفان خواجہ قادر بخش رحمه الله، وشيخ ومرشد شمس العارفین غوثِ زماں سائیں عبدالرزاق رحمه الله. ولقبه أبوسعد. وُلد في جہانخیلاں يوم الجمعة المباركة وقت الصبح الصادق في ٧ شوال ١٢٧٠هـ / ١٨٥٤م. ويقول بنفسه: كنتُ وأنا في الثالثة من عمري أُنادى بين الملائكة بقطب الزمان، وفي السابعة من عمري أمصّني النبي الكريم ﷺ وجميع الأنبياء الكرام ألسنتهم المباركة وقالوا: قد أعطيناك العلم كله. وكان عمره نحو ثلاث سنوات فقط حين استُشهد والده الكريم شمس العرفان خواجہ قادر بخش رحمه الله.", "murshideen.006": "طلب العلم الشرعي", "murshideen.007": "قصد سہارنپور لطلب علم الحديث، فحضر عند مولانا احمد علی محدث رحمه الله، وكان مولانا حسین احمد کانپوری رحمه الله وپیر مہر علی شاہ گولڑوی رحمه الله زميليه في الدرس. ثم أتقن العلوم الدينية إتقاناً تاماً في دہلی على مولوی کریم اللہ صاحب رحمه الله ومولوی سعید احمد رحمه الله. وكان بفضل الله تعالى وكرمه كنزاً من العلوم والكمالات؛ فإذا عُرضت عليه مسألة من أي نوع بيّنها بوضوح مع الإحالات والمراجع بحيث يدهش كبار المفتين. ويكتب خليفته مولوی عبدالکریم جسری صاحب رحمه الله في كتابه «خالقیہ» أن الخواجہ صاحب رحمه الله شخصٌ كامل مكمِّل في هذا الزمان، وعالمٌ كبير من جماعة العلماء.", "murshideen.008": "داعيةً إلى الدين", "murshideen.009": "كان رحمه الله كثيراً ما يخطب قائماً. وكانت ملفوظاته وبياناته الأولى قائمة على الإرشاد والهداية والترغيب في الدين ونشر الإسلام. ولما أمره الله تعالى بخدمة الخلق، تقلّد منصب الخدمة وشمّر عن ساعده لخدمة الخلائق، وقام على وجه الخصوص بخدمتين: تزويج الأرامل، وخدمة اليتامى والمساكين.", "murshideen.010": "السياحة في طلب المرشد", "murshideen.011": "قضى معظم وقته في السفر من السادسة إلى الخامسة والثلاثين من عمره، فسافر في هذا الطلب في الهند كلها وأفغانستان وإيران وبلاد العرب وغيرها. (ويقول بنفسه:) وصلتُ إلى خدمة پیر پٹھان شاہ سلیمان تونسوی رحمه الله، وإلى حاجی امداد اللہ مہاجر مکی رحمه الله عند الكعبة المشرفة، وإلى صاحبان عبدالغنی ومولانا محمد عمر رحمه الله في المدينة المنورة، وإلى غيرهم من الأكابر، ولكني كنتُ أطلب البيعة بشرط: إن أجريتم «الله، الله» من جميع بدني بايعتُ. فكان المشايخ إذا سمعوا هذا الطلب سحبوا أيديهم.", "murshideen.012": "البيعة والخلافة في السلسلة القادرية", "murshideen.013": "يقول: وصلتُ إلى خدمة شیخ احمد بخاری قادری رحمه الله في الٰہ آباد، فلما رآني قال: «برو برو دیگر را بگیر» — أي: اذهب وابحث عن طريق آخر. فأسرعتُ إليه ملهوفاً وتعلّقتُ بقدميه، فرفع رأسي بغاية الشفقة وضمّني إلى صدره، ولما أخذ الشيخ رحمه الله يدي في يده المباركة للبيعة وتوجّه إليّ غُشي عليّ، وكان «الله» حينئذ جارياً من كل شعرة من بدني. وهذا هو ما سمّاه القرآن المجيد الذكر الكثير، ويُسمّى سلطان الأذكار.", "murshideen.014": "وبعد ستة أشهر من الخدمة أراد الشيخ يوماً، أمام جميع الدراويش، أن يعقد عمامة الخلافة على رأسي وقال: أهو أهلٌ لهذا أم لا؟ وقبل أن يجيب أحد قلتُ: إن حمل هذا العبء الثقيل يبدو عسيراً جداً، ولكني أتضرّع إليكم متذلّلاً أن تتحقق أمنية قلبي. قال: وما هي؟ قلتُ: أن تهبوني وجدكم. فلما سمع ذلك قال رحمه الله لجميع الدراويش: كنتم تقولون دائماً إن الشيخ يحبّ هذا الفتى كثيراً، فأخبروني: هل خطر ببال أحدكم قطّ ما سأله هذا الفتى؟ فلما سمعوا ذلك أخذ الوجدُ جميعَ الدراويش. فقال: هذا هو معنى معرفة الأسرار. ثم عقد عمامة الخلافة بيده الطاهرة وقال: اذهب فبايع في السلسلة النقشبندية وأعلِ اسم والدك الكريم، وحيثما كنتَ فأنا معك.", "murshideen.015": "البيعة والخلافة في السلسلة النقشبندية", "murshideen.016": "أخذه الشيخ إلى جالندھر، وجعله يبايع في السلسلة النقشبندية على يد حاجی حافظ محمود جالندھری رحمه الله، شيخ والده الكريم شمس العرفان رحمه الله. ولما كان والده الكريم قد أوصاه بأن يجلس أولاً سبع سنين عند ضريحه وأن يخدم والدته ووالدة أبيه، فقد كان يحضر يومياً عند الضريح المبارك لوالده الكريم بغرض إتمام السلوك النقشبندي، ويتلقى التربية الروحية من الضريح المبارك. وقطع رحمه الله السلوك المجددي في مدة قصيرة، فمنحه الحاجی صاحب رحمه الله عمامة الخلافة.", "murshideen.017": "خدمات شمس الکونین في إحياء السنة", "murshideen.018": "١. تزويج الأرامل", "murshideen.019": "يقول الخواجہ صاحب في كتابه «سرمایۂ سہاگن»: بعد جهدٍ متواصل دؤوب دام أربع سنوات، أقمتُ جلسةً إسلامية في بلدة کلانور بمديرية رہتک من ٢١ مارس إلى ٢٣ مارس ١٨٩٢م الموافق ١٣٠٩هـ، وُضع فيها ثلاثة عشر ألفاً وسبعمائة وخمسة وستون كرسياً، وزُيّنت منصّةٌ كبيرة جداً أُجلس عليها نائب مفوّض رہتک وكبار المسؤولين والعلماء والمشايخ. فأخذت الأرامل يُزوَّجن تباعاً في كبرى أسر کلانور. وبعد ألفٍ وثلاثمائة عام نال شرف إحياء سنة تزويج الأرامل الميتة بحثّ قوم الراجبوت على العمل بأمر الله: ﴿وَأَنكِحُوا الْأَيَامَىٰ مِنكُمْ﴾ (القرآن). وكان قوم الراجبوت قبل ذلك يعدّونه عملاً منافياً للغيرة. ووُزّعت أموال كثيرة على الفقراء والمساكين، ودُعي الجميع إلى وليمة العرس أيضاً.", "murshideen.020": "وأخذ الوجهاء العهد والميثاق، بعد أن وضعوا الماء والملح في الأباريق، قائلين: من اليوم تركنا بطيب خاطر ورضا هذه العادة الهندوسية الكفرية، وقبلنا بقلوبنا وأرواحنا حكم الله ورسوله ﷺ، وسنظلّ دائماً نزوّج الأرامل. ومن لم يعمل بهذا فسيقاطعه جميع الناس ويقطعون معه صلات القرابة والمصاهرة. ومن زوّج أرملةً شاركناه بسرور كما نشارك في زواج البكر، ومن لم يشارك عدّاً له عيباً ومطعناً فلتُخرجه العشيرة منها. وكما أجرينا الزواج الثاني للأرامل، سنُجري الحجاب الشرعي كذلك، أي سنبذل غاية الجهد في أن تحتجب زوجات أبنائنا وبناتنا قدر الإمكان عن غير المحارم.", "murshideen.021": "٢. كفالة اليتيم", "murshideen.022": "كان رحمه الله حيثما ذهب يحثّ على كفالة اليتيم إلى جانب الدعوة إلى تزويج الأرامل، لأن لليتامى صلةً وثيقة بالأرامل. وكان يقول: إن البشارة التي بشّر بها النبي الكريم ﷺ كافلَ اليتيم لم يبشّر بها عابداً ولا زاهداً ولا شهيداً ولا أيَّ صالحٍ مهما عظُم. قال المصطفى ﷺ: أنا وكافل اليتيم في الجنة هكذا كهاتين الإصبعين، وأشار ﷺ بالسبابة والوسطى وضمّهما. فكان رحمه الله يوزّع كل ما يفضل عنده على اليتامى والأرامل.", "murshideen.023": "في ١٥ يونيو ١٩٠٥م أُسّست یتیم خانہ خالقیہ (دار الأيتام الخالقية) وانجمن خالقیہ (الجمعية الخالقية). ثم رُتّب تعليم القرآن الكريم. وبعد ذلك اعتُمدت المدرسة الابتدائية في ١٩٠٦م، والمتوسطة في ١٩١٤م، والثانوية في ١٩٢٥م، ثم الكلية المتوسطة. وانتفع بهذه المؤسسات أبناء الهندوس والسيخ أيضاً؛ فكان يدرس فيها أبناء المسلمين والبراهمة والبانيا والسيخ والشمار، وجاء ثلاثة أطفال أيتام من أفريقيا أيضاً للتعليم.", "murshideen.024": "وكذلك سجّل سید امیر حسین شاہ صاحب، المقيم في رحیم یار خان، تسعة عشر «مربعاً» من الأرض باسمه رحمه الله ليبني له زاويةً متينة. لكنه رحمه الله سجّل الأرض كلها باسم دار الأيتام وقال: لا حاجة لنا بالأراضي. وظلّ رحمه الله يسكن دائماً في بيت من الطين مسقوف بالقشّ، لكنه بنى بيوتاً متينة لليتامى والمسافرين وموظفي المدرسة. وإذا لقي مسؤولاً جاء إلى بابه صافحه بيد واحدة، وما قدّمه المسؤولون من هدايا لم يحتفظ به لنفسه بل أودعه دار الأيتام، وقال لصاحبه: أودعنا هديتك دار الأيتام لكي يعطيك الله الكريم بدلها ألف ضعف في الدنيا والآخرة. وإذا جاء ضيفٌ بحلوى ونحوها وزّعها بيده الحانية على اليتامى والدراويش اتباعاً للسنة.", "murshideen.025": "٣. حماية ختم النبوة", "murshideen.026": "لما ادّعى مرزا غلام احمد قادیانی النبوة كذباً، اجتمع آلاف من أهل الإسلام في لاہور عام ١٩٠٢م للمباهلة، واختير من جانب أهل السنة والجماعة ثلاثة أعلام: شمس الکونین خواجہ محمد عبدالخالق رحمه الله، وپیر مہر علی شاہ گولڑوی رحمه الله، وانور شاہ کشمیری رحمه الله. فاشترط مرزا قادیانی للمباهلة أن يوضع في الميدان قلمٌ ودواةٌ خاليان، وأن القدرة الإلهية ستصدّق نبوته. فقبل هؤلاء الأعلام ذلك. وفي اليوم التالي أخذ الناس يتوافدون أفواجاً إلى ميدان المباهلة، ووصل هؤلاء الأكابر الثلاثة أيضاً، لكن مرزا قادیانی بدلاً من أن يحضر إلى الميدان فرّ إلى قادیان.", "murshideen.027": "في ديسمبر ١٩٢٤م كان رحمه الله مقيماً عند الروضة المباركة لـمجدد الفِ ثانی رحمه الله في سرہند شریف. فكتب إليه مسلمو مديرية رنگ پور في البنغال أن ابن مرزا قادیانی، مرزا بشیر الدین قادیانی، يتحدّى المسلمين بالمباهلة، فهل أنتم مستعدون للمباهلة؟ فأجاب: أنا مستعد للمباهلة بهذه الشروط: (١) أن يعلن هو بنفسه تاريخ المباهلة. (٢) أن يكون مكان المباهلة في مدينة كبيرة من مدن الهند مثل دہلی أو لاہور أو کلکتہ أو بمبئی. (٣) أن تكون المباهلة في جمعٍ عام. فلما سمع مرزا هذه الشروط فرّ إلى البنجاب.", "murshideen.028": "٤. إحياء الصلاة في أول الوقت", "murshideen.029": "في عام ١٩٢٥م رأى رحمه الله في المنام أن شيخاً مشهوراً في زمانه يُعذَّب عذاباً شديداً، فعُلم أن هذا العذاب بسبب تأخيره الصلوات وتركه الجماعة. ومنذ ذلك الحين صار يبادر مبادرةً شديدة في أداء جميع الصلوات، ولا سيما الفجر والظهر، وكان يقيم الصلاة جماعةً بمجرد دخول وقتها بحسب مواقيت المذهب الحنفي.", "murshideen.030": "قال الله تعالى في سورة الماعون: <span class=\"kk-ar\" style=\"display:block\">فَوَيْلٌ لِّلْمُصَلِّيْنَ ۝ الَّذِيْنَ هُمْ عَنْ صَلَاتِهِمْ سَاهُوْنَ</span> — أي إن الويل، وهو عذاب وادٍ في جهنم، لأولئك المصلين الذين يتهاونون في صلاتهم. وقال النبي الكريم ﷺ ما معناه: أداء الصلاة في أول وقتها سببٌ لرضا الحق تعالى.", "murshideen.031": "وكان المشايخ ذوو المراتب العالية، أمثال امام غزالی رحمه الله، وسیدنا شیخ عبدالقادر جیلانی رحمه الله، وامامِ ربانی مجدد الفِ ثانی رحمه الله، وشاہ غلام علی دہلوی رحمه الله، يؤدّون الصلاة في أول وقتها ويوصون بذلك مريديهم. ثم إن كل ذي فهم يدرك جيداً أن تأخير الصلاة بعد صدور أمر الرب بغير عذر شرعي بعيدٌ عن دعوى المحبة وقريبٌ من مخالفة الأمر، بينما العبد المحبوب هو الذي يخرّ ساجداً بين يدي ربه بمجرد دخول الوقت. فينبغي السعي إلى أداء الصلاة في أول الوقت.", "murshideen.032": "الوفاة المباركة", "murshideen.033": "نحو الساعة الواحدة ليلاً أيقظ السائیں صاحب رحمه الله وقال: وضّئني وصلِّ بي نوافل التهجد. وبعد النوافل سجد ودعا: اللهم لا تُذقني ألم سكرات الموت، وارزقني درجة الشهادة وأنا ساجد. وبعد الدعاء قال: يا عبدالرزاق، إني الآن في قلق شديد، فاستمرّ في تدليكي. وهكذا حان وقت الفجر، فتوضأ رحمه الله وأدى سنة الفجر. وأقيمت الجماعة، وكان معه مأمومون: سید دین علی شاہ رحمه الله، وسائیں عبدالرزاق رحمه الله، ومولوی سراج الدین. وفي السجدة الأخيرة من الركعة الثانية سقط السقف كله فجأة، وفي ٧ محرم الحرام ١٣٥٠هـ، عن عمر مبارك بلغ ٨٠ سنة، انتقل رحمه الله إلى خالقه الحقيقي.", "murshideen.034": "شمس العارفین سائیں عبدالرزاق خالقی نقشبندی رحمه الله<span class=\"mk-hint\">اقرأ التعريف ▾</span>", "murshideen.035": "شمس العارفین، سراج السالکین<br>قطب العالم حضرة سائیں عبدالرزاق خالقی نقشبندی رحمه الله", "murshideen.036": "الكشف والكرامات أمرٌ من درجةٍ دنيا، وإنما الأصل اتباع السنة والتزام الشريعة المطهرة، لأن المريدين ينظرون إلى عمل شيخهم فيقتدون به. (شمس العارفین رحمه الله)", "murshideen.037": "وكان كثيرًا ما يقول: الشريعة بذرة، فإن كانت البذرة فاسدة فكيف تصلح الشجرة؟ الشريعة هي الأول، والشريعة هي الآخر. ولو جاء أحدٌ طائرًا في الهواء وهو تاركٌ للشريعة ولو بمقدار شعرة، فقد يكون ساحرًا، ولكن لا يمكن أن يكون من أولياء الله.", "murshideen.038": "المولد المبارك", "murshideen.039": "وَفقًا لما أخبر به رحمه الله، كانت ولادته المباركة سنة ۱۸۹۰م. وبعد ولادته أرسلته جدته إلى المسجد طلبًا لحسن الطالع وطول العمر. وكان يقول: من فضل الله تعالى أن عمري كله قد مضى في المساجد.", "murshideen.040": "التعليم الأوّلي", "murshideen.041": "ولما بلغ الخامسة أو السادسة من عمره بدأ يواظب على الصلوات الخمس، ومنذ السابعة أو الثامنة من عمره بدأ يواظب على صلاة التهجد، ولم تَفُتْه بفضل الله تعالى حتى آخر نفس.", "murshideen.042": "حين بدأتَ صلاة التهجد لم يكن عمرك إلا سبع سنين فقط.", "murshideen.043": "لم تفتك تكبيرة الإحرام ولم تَقضِ صلاة قط؛ يا سيدي سائیں المحبوب، ما أعظم شأنك!", "murshideen.044": "تلقّى تعليمه الأوّلي في مدرسة كلانور، وترك المدرسة بعد الصف الثاني بسبب حال الجذب التي كانت تعتريه. وقرأ القرآن الكريم على إمام المسجد الحافظ عبدالرحمن صاحب.", "murshideen.045": "الحضور في خدمة الخواجه صاحب رحمه الله", "murshideen.046": "يقول أكابر أهل الدين: من أراد أن يكون من المقرّبين إلى الله فليلزم صحبة أولياء الله.", "murshideen.047": "فلما بلغ من العمر المبارك اثنتي عشرة سنة، أخذه والده إلى خدمة الخواجه صاحب رحمه الله، فحمله الخواجه صاحب في حِجره وقبّله. فقال والده: إن هذا الولد يبكي دائمًا ويقرأ القرآن الكريم ولا يكلّم أحدًا، فليتَه يصير مدركًا لأمر الأكل والشرب واللبس والكلام. فقال الخواجه صاحب رحمه الله: سيتزوج، وسيُرزق بالأولاد، وسيعمل في وظيفة، وسيكون سيدًا، وقد كُتب اسمه في قائمة عباد النبي الكريم ﷺ المقبولين. ويقول رحمه الله بنفسه: إن ما جرى عليّ بنظرة الفيض من الخواجه صاحب رحمه الله لا يمكن وصفه. وفي تلك الأثناء بايع الخواجه صاحب رحمه الله.", "murshideen.048": "قطع منازل السلوك", "murshideen.049": "قال حضرة سائیں جی رحمه الله: بقيتُ في خدمة الخواجه صاحب رحمه الله أربعين سنة، ولم أتكلم أمامه قط. وفي يومٍ من الأيام كان الخواجه صاحب رحمه الله راكبًا على ظهري، وكان السيد دين علی شاہ صاحب رحمه الله يحمل نعليه المباركتين، فدعا رحمه الله باكيًا بهذا الدعاء:", "murshideen.050": "يا الله! ارضَ عن عبدالرزاق هذا بقدر ما أنا راضٍ عنه، وكما خدمني فليخدمه الخلق بقدر ذلك.", "murshideen.051": "وقال السيد دين علی شاہ صاحب رحمه الله مرةً للخواجه صاحب رحمه الله: يا حضرة! لو كان عبدالرزاق في الجيش لكان اليوم قائدًا. فجلس رحمه الله وقال: يا شاه جي! ماذا تظن؟ إن قادة الجيش سيتمرّغون عند قدميه. وكان رحمه الله يقول عن نفسه: ليس عندي علم، ولم أُدِر سُبحة، ولم أواظب على أوراد ووظائف، وإنما هذا كله فيضُ صحبة الخواجه صاحب رحمه الله ونظرته ودعائه وبركته. وما رفعتُ عيني قط لأنظر أمام الخواجه صاحب رحمه الله، ولا تكلمتُ أمامه قط.", "murshideen.052": "بقيتَ عند الشيخ ستًّا وثلاثين سنة، وكانت رؤية الشيخ وحدها هي وِردك.", "murshideen.053": "لم تفارقه حتى آخر نفس؛ يا سيدي سائیں المحبوب، ما أعظم شأنك!", "murshideen.054": "كفالة الأيتام", "murshideen.055": "لم يكن له نظير في كفالة الأيتام، وكان يُرى دائمًا قلقًا مضطربًا من أجل إعانة الأطفال الأيتام المنكوبين الذين نبذهم المجتمع ومساعدتهم.", "murshideen.056": "وفي هذا الصدد روى الحافظ علیم الدین صاحب أنه في سنة ۱۹۶۵م عاد حضرة سائیں جی رحمه الله من الحج، فجاء كثيرٌ منا من دیپالپور شریف إلى محطة أوكاڑہ لاستقباله. وجاء موج دین رزّاقی بقلادة من ورود الجوري، فأنزلنا الحضرة من القطار، وأراد موج دین أن يضع القلادة في عنقه، لكن الحضرة وضعها في عنق موج دین وقال: هذا إسراف ورياء، ولو أودعتم هذا المال في دار الأيتام لكان خيرًا.", "murshideen.057": "وكان يقول: ينبغي أن يُعامَل اليتيم معاملةً لا يشعر معها بشيءٍ من اليُتم. فإن كنتم ستربّونه بأن تجعلوه يتسوّل، فهو قادر على أن يُطعم نفسه بنفسه، فأيّ فضلٍ لكم؟ بل إن جمع التبرعات بواسطة الأيتام ثم الانتفاع بها شخصيًا كلاهما حرام.", "murshideen.058": "ولإعادة تأهيل الأطفال الأيتام إعادةً دائمة، أنشأ في أماكن مختلفة من البلاد بنفقات بلغت مئات الآلاف من الروبيات دُورًا للأيتام باسم «دار الشفقت»، وأقام إلى جانبها مساجد ومؤسسات تعليمية. وكان مئات الأيتام والأطفال الذين لا عائل لهم المقيمون في تلك الدور يتلقّون مع التعليم الديني تعليمًا عصريًا ومهنيًا، فيصيرون بذلك قادرين على أن يعيشوا حياةً كريمةً موقّرة بدلًا من أن يكونوا عبئًا على المجتمع. وكانت هذه المؤسسات مسجّلة ومعتمدة رسميًا لدى الحكومة، وكانت الامتحانات فيها تُجرى تحت إشراف المجلس التعليمي (البورد).", "murshideen.059": "وكان رحمه الله قد قسّم أرضه الزراعية الموروثة بين أولاده ليعيشوا عيشًا كريمًا، ووهب سائر أملاكه في المدينة باسم دار الأيتام. بل إنه قبل وفاته أودع مبلغ مئة وثلاثة وعشرين ألف روبية من الهدايا (النذرانة) في صندوق دار الأيتام، وقال: إن كان الأولاد صالحين أكفاء فسيكسبون بأنفسهم، وإن كانوا غير أكفاء فسيُضيّعون حتى ما كان لديهم. ينبغي الإنفاق في سبيل الله، فهو الذي ينفع في الآخرة.", "murshideen.060": "لقب «سراج السالكین»", "murshideen.061": "يروي رسالدار محمد لقمان رزّاقی صاحب أنه كثيرًا ما كان يخطر بباله سؤال: كيف ينال عباد الله الخواص ألقابًا مختلفة؟ وفي يومٍ قبيل صلاة الفجر بقليل كان جالسًا في المسجد فغلبه النعاس، فرأى الإمام الرباني مجدد الألف الثاني رحمه الله وقبلة العالم حضرة سائیں جی رحمه الله واقفين أمام محراب المسجد. فضمّ حضرة المجدد صاحب رحمه الله سائیں صاحب إلى صدره ثم قال: تعالَ نختمك بخاتم «سراج السالكین». ثم استيقظ، وهكذا وجد جواب سؤاله.", "murshideen.062": "لقب «شمس العارفین»", "murshideen.063": "ذهب رحمه الله مرةً إلى مرالہ شریف لزيارة چراغ علی شاہ رحمه الله، خليفة السيد جماعت علی شاہ رحمه الله، الذي يقع ضريحه المبارك في والٹن بلاهور. فخلع الشاه صاحب رحمه الله عمامته ووضعها في عنقه، ورفع ذراعيه كلتيهما وقال: ماذا أقول عمّن جاء إلى بيتي! إن الشريعة تمنعني، ولكن اعلموا أن «نرائن» قد جاء إلى بيت النملة. فقال حضرة سائیں جی رحمه الله: إن شاه جي درويش عظيم جدًّا، وهو مالك ربع الدنيا. فقال شاه جي: لقد كشفتَ سرّي يا سيدي، أعتذر، ولم أعد أستطيع الصبر، فأنا أيضًا أكشف سرّك: إنك مالك الدنيا كلها، وأنت في هذا الوقت فريدٌ لا ثاني له. وقال الشاه صاحب رحمه الله مرةً: إن لقب حضرة سائیں جی هو «شمس العارفین».", "murshideen.064": "الوفاة المحزنة", "murshideen.065": "كان رحمه الله نزيلًا في مستشفى كنعان ترسٹ بلاهور لإجراء عملية جراحية للبواسير، وكان سريره يُوضع في الصف الأول، ويُيمَّم بالتراب، فيصلّي مع الجماعة مستلقيًا بالإيماء. وفي ۲۴ مارس ۱۹۸۲م أُدخل مرةً أخرى مستشفى كنعان ترسٹ بلاهور.", "murshideen.066": "وأخيرًا في ليلة الثلاثاء أصابه الاستغراق، وبقي في حال الاستغراق نحو عشرين ساعة، ثم انتقل إلى خالقه الحقيقي في الساعة الرابعة عصرًا يوم الأربعاء ۳۱ مارس ۱۹۸۲م الموافق ۴ جمادى الآخرة ۱۴۰۳هـ، عن عمرٍ مبارك يناهز خمسًا وتسعين سنة. وعند الوفاة رفع سبّابتَي يديه كلتيهما، وجرى على لسانه المبارك اسم الذات «الله». وبعد الوفاة رأى الجميع أن القلب السليم كان متحركًا بذكر الله. وفور الوفاة المباركة أُذيع من إذاعة باكستان في لاهور هذا الإعلان: إن شمس الطريقة بعد أن أضاءت قرابة قرنٍ من الزمان قد غربت اليوم الأربعاء ۳۱ مارس ۱۹۸۲م الموافق ۴ جمادى الآخرة ۱۴۰۳هـ.", "murshideen.067": "غُسّل الجسد المبارك، ولُفّ وفقًا لوصيته في الملاءة التي كانت على جسد الخواجه صاحب رحمه الله وقت استشهاده، ووُضعت شعرات الخواجه صاحب رحمه الله المباركة أيضًا في كفنه. ونظرًا للجمع الغفير صُلّيت عليه صلاة الجنازة ثلاث مرات. ويوم الجمعة ۲ أبريل، ووفقًا لوصيته، وُضع الجسد المبارك معلّقًا في صندوق خشبي ووُوري الثرى.", "murshideen.068": "الخلفاء الكرام وأصحاب السجادة", "murshideen.069": "خلفاؤه رحمه الله المشهورون ثلاثة، وأسماؤهم الكريمة كما يلي:", "murshideen.070": "١. امام الذاکرین حضور سائیں محمد عظیم اللہ رزّاقی نقشبندی رحمه الله، الدربار العالية عظیم نگر شریف، مديرية بہاولنگر.<br>٢. بے حد سوہنے خواجہ نور احمد خاں رزّاقی نقشبندی رحمه الله، الدربار العالية لالہ موسیٰ شریف، مديرية گجرات.<br>٣. المحامي حضور محمد شریف رزّاقی نقشبندی رحمه الله، الدربار العالية سیل گاؤں، مديرية پاکپتن شریف.", "murshideen.071": "وكان له رحمه الله ابنان، وأسماؤهما الكريمة كما يلي:", "murshideen.072": "١. صاحبزادہ فقیر محمد رزّاقی نقشبندی، أدام الله ظلّه علينا طويلًا.<br>٢. صاحبزادہ بلال احمد رزّاقی نقشبندی رحمه الله، وكانت وفاته سنة ۲۰۲۵م. رفع الله درجاته.", "murshideen.073": "امام الذاکرین سائیں محمد عظیم اللہ رزّاقی نقشبندی رحمه الله<span class=\"mk-hint\">اقرأ التعريف ▾</span>", "murshideen.074": "امام الذاکرین، سراج السالکین، قطبِ دوراں<br>مظہرِ نورِ خدا قبلۂ عالم سائیں محمد عظیم اللہ رزّاقی نقشبندی رحمه الله", "murshideen.075": "المولد والطفولة", "murshideen.076": "وفقًا لبطاقة الهوية، وُلد رحمه الله في الأول من يناير ۱۹۳۴م في قرية سیہوانی بمديرية حصار في الهند، في بيت الحاج حسین علی صاحب رحمه الله، وهو رجل صالح السيرة من أسرة راجبوتية. وكانت والدته الماجدة من حيّ میر خان في ڈھنکوٹ، وتقيم أسرتها حاليًا في گوٹھ محمد ابڑو. وكان في طفولته كثير المرض، يلزم الصمت أو يبكي.", "murshideen.077": "بيعة الطريقة", "murshideen.078": "يقول الله تعالى في سورة المائدة: <span class=\"kk-ar\" style=\"display:block\">يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوا اتَّقُوا اللّٰهَ وَابْتَغُوْٓا اِلَيْهِ الْوَسِيْلَةَ وَجَاهِدُوْا فِيْ سَبِيْلِهٖ لَعَلَّكُمْ تُفْلِحُوْنَ</span> يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَابْتَغُوا إِلَيْهِ الْوَسِيلَةَ وَجَاهِدُوا فِي سَبِيلِهِ لَعَلَّكُمْ تُفْلِحُونَ (۳۵)", "murshideen.079": "وكان شيخنا يروي قصة بيعته بنفسه فيقول: حين كنت أدرس في الصف الخامس جاء من يجنّدون للجيش، فتجنّدتُ مع غيري من الفتيان. وفي تلك الأيام كان حضرة سائیں جی رحمه الله نازلًا في ديرة راؤ مراتب علی في ڈونگہ بونگہ، فحضرتُ لزيارته، فبايعني سائیں جی رحمه الله في الحال.", "murshideen.080": "وبعد ذلك قدم حضرة سائیں جی رحمه الله إلى سونڈھا شریف، فلما رأته والدتي قالت فورًا: هذا هو الشيخ نفسه الذي أرانيه أحد العاملين (الروحانيين) في ظفري في الهند. فوقفت والدتي في الطريق وقالت لسائیں جی رحمه الله: لقد وهبتُك عظیم اللہ منذ زمن بعيد. فقال سائیں جی رحمه الله: نعم، إنه لي. وفي سنة ۱۹۵۵م أخذني حضرة سائیں جی رحمه الله معه إلى دیپالپور شریف، وفي يومٍ وهو يغسل الثياب طلب كتلةً من صبغ المَغْرة (الگيرو)، فصبغ ثيابه وصبغ ثيابي معها بلون المغرة.", "murshideen.081": "منصب الخلافة", "murshideen.082": "وكان رحمه الله يروي قصة منحه منصب الخلافة من حضرة سائیں جی رحمه الله فيقول: كان حضرة سائیں جی رحمه الله جالسًا في مسجد دیپالپور شریف، فذهبتُ بعد حلقة الذكر الصباحية إلى صحن المسجد وأخذت أنقّي القمح. فدعاني حضرة سائیں جی رحمه الله بعد المراقبة، وضمّني بذراعه اليمنى وقال: علِّم الناس ذكر «الله الله». فقلت: يا حضرة، الناس كلهم يذكرون «الله الله» كثيرًا. فقال: اجعلهم مريدين أولًا، ثم علّمهم «الله الله». فغلبني حينئذٍ خوف شديد، وتصبّب العرق من جسدي كله. فقال: لقد قال لي الخواجه صاحب رحمه الله هكذا أيضًا: أَلقِ التوجّه هكذا، وعلّم ذكر «الله الله» هكذا.", "murshideen.083": "لقب «امام الذاکرین»", "murshideen.084": "كان على المؤلف الفقير أن يطبع إعلانات في قريته بمناسبة العرس السنوي المبارك لحضرة سائیں جی رحمه الله، فنام وهو حائر أيّ لقبٍ يليق بشأن حضرة قبلة العالم رحمه الله يكتبه مع اسمه المبارك. فرأى في المنام أنه واقف عند القبر المنوَّر لحضرة سائیں جی رحمه الله، وأن ما حول ضريحه، إلى حيث يمتد بصره، كان نورًا على نور من الأرض إلى العرش، وجاء صوتٌ من قبره المنوَّر: عظیم اللہ هو «امام الذاکرین».", "murshideen.085": "الوفاة المباركة", "murshideen.086": "وبعد مرضٍ طويل انتقل إلى خالقه الحقيقي في ۱۴ جمادى الأولى ۱۴۳۴هـ الموافق ۲۷ مارس ۲۰۱۳م، يوم الأربعاء، في الساعة الثامنة صباحًا، في سونڈھا شریف، وهو يذكر الله، عن عمرٍ يناهز ثلاثًا وثمانين سنة. وبحسب قول أخته الصغرى حکومت بی بی، فقد قال رحمه الله قُبيل وفاته: إن حضرة سائیں جی جالسٌ عندي.", "murshideen.087": "ودُفن يوم الجمعة المباركة ۲۹ مارس على طريق بہاولنگر قبل ڈونگہ بونگہ بقليل عند منعطف سورج گنج، قرب صحن مسجده، حيث يُبنى الآن روضته المقدسة على تصميم الضريح الأقدس لسائیں حضور رحمه الله. وما زال خلق الله ينهلون من فيضه ليلًا ونهارًا.", "murshideen.088": "ستُضاف الصور وتفاصيل المزارات قريبًا إن شاء الله.", "mubalighin.001": "التعريف بالمبلّغين", "mubalighin.002": "ستُضاف الصور ومقاطع الفيديو قريبًا إن شاء الله.", "markaz.001": "المركز الرئيسي", "marakiz.001": "المراكز والمدارس الفرعية", "marakiz.002": "اسلام پور", "marakiz.003": "کوٹلی نجابت", "marakiz.004": "وہاڑی", "marakiz.005": "کوٹ مصری خان", "marakiz.006": "مہاجر گوٹھ", "marakiz.007": "گوٹھ ابڑو", "marakiz.008": "35 چک", "marakiz.009": "راؤ گڑھ", "marakiz.010": "ستُضاف تفاصيل بقية المراكز والمدارس قريبًا إن شاء الله.", "bayanat.001": "البيانات", "bayanat.002": "اضغط على أي بيان — يُعرض الفيديو على يوتيوب.", "kutub.001": "الكتب", "kutub.002": "حرف حرف تاثیر", "kutub.003": "<span>المؤلف:</span> مؤسس وقائد تحریک اتباعِ سنت پاکستان، العالم الديني کرامت علی رزّاقی عظیمی مجددی نقشبندی <span class=\"lat\">(M.A, L.L.B)</span>", "kutub.004": "<span>بمساعدة:</span> المهندس شعیب عالم عظیمی مجددی (ماجستير في العلوم الإسلامية)، <span class=\"lat\">HOD</span> تخصص الكهرباء، المعهد الحكومي للتدريب الفني، لودھراں", "kutub.005": "عدد الصفحات: <span class=\"lat\">136</span>  • النشر: أكتوبر <span class=\"lat\">2026</span>", "kutub.006": "تعريف بتحریک اتباعِ سنت پاکستان وأهدافها", "kutub.007": "هدفنا: نشر الشريعة والسنة", "kutub.008": "<span>المؤلف:</span> مؤسس وقائد التحريك، شيخ الطريقة کرامت علی رزّاقی عظیمی نقشبندی <span class=\"lat\">(M.A, L.L.B)</span>", "kutub.009": "عدد الصفحات: <span class=\"lat\">19</span>", "kutub.010": "صراط الفلاح فی الدنیا والآخرۃ", "kutub.011": "طريق الفلاح في الدنيا والآخرة", "kutub.012": "<span>المؤلف:</span> مؤسس وقائد تحریک اتباعِ سنت پاکستان، شيخ الطريقة کرامت علی رزّاقی عظیمی نقشبندی <span class=\"lat\">(M.A, L.L.B)</span>", "kutub.013": "<span>بمساعدة:</span> المهندس شعیب عالم عظیمی مجددی (ماجستير في العلوم الإسلامية)، <span class=\"lat\">HOD</span> تخصص الكهرباء، المعهد الحكومي للتدريب الفني، لودھراں", "kutub.014": "عدد الصفحات: <span class=\"lat\">83</span>  • النشر: مارس <span class=\"lat\">2019</span>", "kutub.015": "دستورِ طریقت", "kutub.016": "المعروف بـ«راہِ سلوک» (طريق السلوك)", "kutub.017": "<span>المؤلف:</span> مؤسس وقائد تحریک اتباعِ سنت پاکستان، شيخ الطريقة، شیرِ مجدد بدرالہدیٰ کرامت علی رزّاقی عظیمی نقشبندی <span class=\"lat\">(M.A, L.L.B)</span>", "kutub.018": "<span>بمساعدة:</span> المهندس شعیب عالم عظیمی مجددی (ماجستير في العلوم الإسلامية)، <span class=\"lat\">HOD</span> تخصص الكهرباء، المعهد الحكومي للتدريب الفني، لودھراں", "kutub.019": "عدد الصفحات: <span class=\"lat\">129</span>  • النشر: أكتوبر <span class=\"lat\">2016</span>", "gallery.001": "معرض الصور", "bait.001": "البيعة والطريقة", "bait.002": "بيعة الطريقة", "bait.003": "يقول الله تعالى في سورة المائدة: <span class=\"kk-ar\" lang=\"ar\" style=\"display:block\">يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوا اتَّقُوا اللّٰهَ وَابْتَغُوْٓا اِلَيْهِ الْوَسِيْلَةَ وَجَاهِدُوْا فِيْ سَبِيْلِهٖ لَعَلَّكُمْ تُفْلِحُوْنَ</span> يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَابْتَغُوا إِلَيْهِ الْوَسِيلَةَ وَجَاهِدُوا فِي سَبِيلِهِ لَعَلَّكُمْ تُفْلِحُونَ (۳۵)", "bait.004": "يقول الشاه ولي الله المحدّث الدهلوي: إن المراد بالوسيلة في هذه الآية هو المرشد الكامل.", "bait.005": "يقول الله تعالى في سورة لقمان: <span class=\"kk-ar\" lang=\"ar\" style=\"display:block\">وَاتَّبِعْ سَبِيْلَ مَنْ اَنَابَ اِلَيَّ</span> وَاتَّبِعْ سَبِيلَ مَنْ أَنَابَ إِلَيَّ (۱۵)", "bait.006": "وفي شأن بيعة الطريقة والإرادة يقول سيدنا عبادة بن الصامت الأنصاري رضي الله عنه: بايعنا رسول الله ﷺ على السمع والطاعة لأمره ﷺ في العسر واليسر، والمنشط والمكره، وعلى ألّا نعترض على شيءٍ من أمره ﷺ. (البخاري، كتاب الأحكام)", "bait.007": "يقول حجة الإسلام الإمام الغزالي رحمه الله: ليس أحدٌ سوى الأنبياء الكرام عليهم السلام خاليًا من الأمراض الظاهرة والباطنة، ولذلك فإن الدخول في الطريقة مع الصوفية ضروري لإزالة تلك الأمراض. وكما هو مقرَّر في علم الطب أن أحدًا لا يستطيع أن يعالج نفسه بنفسه رغم قراءته كتب الطب، بل لا بد له من طبيب، فكذلك أمراض القلب والنفس لا يمكن علاجها ذاتيًا، بل لا بد لها أيضًا من مرشدٍ كامل.", "bait.008": "يقول سيدنا عبدالقادر عيسى الشاذلي رحمه الله: إن الصحابة الكرام رضي الله عنهم أصحاب النبي الكريم ﷺ لم يكونوا يستطيعون علاج نفوسهم بمجرد قراءة القرآن، بل كانوا هم أيضًا مرتبطين بمشفى طبيب الكونين الحاذق ﷺ، وكان ﷺ يزكّي نفوسهم ويصفّي قلوبهم. (حقائق عن التصوف)", "bait.009": "يقول جدّنا المرشد شمس الکونین فاتحِ قادیانیت خواجہ محمد عبدالخالق رحمه الله: إن كلمة «البيعة» مشتقة من «البيع» ومعناه أن يُباع المرء. فحين يبايع المريد فإنه يسلّم جميع إراداته إلى شيخه. والشيء إذا بيع لا يمكن استرداده إلا بتراضي الطرفين، فكيف يمكن أن يبيعه في مكانٍ آخر؟ (لمعاتِ کمالاتِ قادریہ)", "bait.010": "مقصد بيعة الطريقة", "bait.011": "يقول الإمام الرباني مجدد الألف الثاني رحمه الله: للشريعة ثلاثة أجزاء: العلم والعمل والإخلاص، والطريقة وسيلةٌ لتحصيل الجزء الثالث من الشريعة وهو الإخلاص. فالطريقة ليست شيئًا منفصلًا عن الشريعة، بل هي خادمة للشريعة في تكميلها.", "bait.012": "فالمقصد الأصلي من البيعة هو الإخلاص، أي نيل رضا الله تعالى. ووسيلته السير التام على الأحكام الشرعية والسنة النبوية ﷺ، والرضا بمشيئة الله تعالى، وترك الحرص، وحضور القلب في العبادة، والقيام بأعمال الدين بإخلاص، وألّا يحتقر أحدًا، وألّا يكون معجبًا بنفسه، وكظم الغيظ، والاشتغال بالذكر والفكر. والتخلّق بمثل هذه الأخلاق يسمّى سلوكًا.", "bait.013": "وينبغي أن يُعلم أنه لا يلزم في ذلك الكشف والكرامات، ولا فيه وعدٌ بالنجاح في الأمور الدنيوية، ولا ادعاءُ شفاء الأمراض بالرُّقى والنفث، ولا الإخبارُ بما سيقع من أحداث، ولا تلزم التصرفات بحيث يصلح المريد تلقائيًا بتوجّه الشيخ، ولا توجد مدة محددة لحصول أحوالٍ باطنة يكون معها المريد دائمًا، أو على الأقل وقت العبادة، غارقًا في اللذة منتشيًا لا تخطر له الخواطر في العبادة، ولا يلزم في الذكر والشغل رؤية الأنوار ونحوها أو سماع صوت ما، ولا يلزم رؤية الرؤى الحسنة أو صحة الإلهامات وصوابها.", "bait.014": "شروط الشيخ الكامل", "bait.015": "إن التزوير والشعوذة في زماننا قد بلغا الذروة، ويُقدَّم الوجه الحقيقي للتصوف مشوَّهًا. ولذلك تُذكر هنا استطرادًا خمسة شروط للشيخ الكامل، ليتمكّن سالكو الطريقة من التمييز بأنفسهم بين الأصيل والمزيَّف، فيحموا أنفسهم من الضلال.", "bait.016": "يقول أعلى حضرت الإمام أحمد رضا خان البريلوي رحمه الله في شروط الشيخ الكامل:", "bait.017": "<b class=\"az-n\">١. العقيدة:</b> أن يكون الشيخ صحيح العقيدة على مذهب أهل السنة والجماعة، لأن سلسلة المبتدع الضال تنتهي إلى الشيطان لا إلى رسول الله ﷺ. (وفي زماننا إن كانت عقيدة شيخٍ ما مخالفةً لأفضلية الشيخين، أي الصديق وعمر رضي الله عنهما، أو كان لا يحمل رأيًا حسنًا في سيدنا أمير معاوية رضي الله عنه، فعلى المريد السني أن ينقض بيعة هذا الشيخ فورًا ويبايع شيخًا صحيح العقيدة).", "bait.018": "وفي صحة العقيدة يقول قيوم الزمان ميرزا مظهر جان جاناں الشهيد الدهلوي رحمه الله: يلزم إظهار المحبة لأهل البيت الأطهار، وتعظيم الصحابة الكرام رضي الله عنهم على السواء. وهذا هو الصراط المستقيم الذي سيظهر يوم القيامة في صورة الصراط (الجسر)، فمن لم ينحرف عن هذا الطريق في الدنيا عبره يوم القيامة بثبات. (مقاماتِ مظہری)", "bait.019": "<b class=\"az-n\">٢. العلم:</b> يُشترط من العلم قدرٌ يستطيع به أن يستخرج مسائل حاجاته من الكتب دون مساعدة أحد. ويمكن أن يصير عالمًا بالمطالعة وبالسماع من الناس أيضًا. وشهادة التخرج ليست شرطًا ولا كافية، بل المطلوب أن يكون عنده علم. وأن يكون مطّلعًا على أحكام الشريعة من أمرٍ ونهي، وحلالٍ وحرام، وفرضٍ وواجب، وسنةٍ ومستحب، وكفرٍ وإسلام، أي على علم الفقه، وأن يستطيع قراءة العبارة العربية قراءةً جيدة.", "bait.020": "يقول جدّنا المرشد شمس الکونین خواجہ محمد عبدالخالق شمس العرفانی نقشبندی رحمه الله:", "bait.021": "<b class=\"az-n\">٣. العمل:</b> أن يكون عاملًا بعلمه، فلا يفوته فرضٌ ولا سنةٌ ولا مستحب، حتى إنه يستعمل المشط والسواك، ويصلّي مع الجماعة، ولا يترك الجمعة. وأن يكون متمسكًا بالشريعة بقوة، ولا يقصّر في متابعة المصطفى ﷺ.", "bait.022": "<b class=\"az-n\">٤. الإخلاص:</b> يقول شمس الکونین خواجہ عبدالخالق رحمه الله: ينبغي أن يكون كل عملٍ من أعمال الشيخ ابتغاءً لرضا الله تعالى.", "bait.023": "<b class=\"az-n\">٥. السلسلة والخلافة:</b> أن تكون سلسلة طريقة الشيخ صحيحة، أي أن يكون مريدًا لشيخٍ ما وحاصلًا على الخلافة منه، حتى تتصل يده يدًا بيد إلى رسول الله ﷺ. ومن يأخذ البيعة بغير خلافة فإن أهل الطريقة يعدّونه زنديقًا، وهو ضالّ. وبعض الناس دون أن يكونوا مريدين، وبمجرد ظنهم أنهم أبناء مشايخ، يجلسون على السجادة عند أضرحة آبائهم وأجدادهم. أو تكون السلسلة نفسها قد قُطعت ولم يُجعل فيها فيض، والناس يمنحون الخلافة فيها اتباعًا للهوى، أو كانت السلسلة صحيحة لكن جاء في وسطها شخص غير أهلٍ للمشيخة فالفرع الذي تفرّع منه منقطعٌ في وسطه. وفي جميع هذه الصور لن تصل مثل هذه البيعة أبدًا إلى يد رسول الله ﷺ، ولن يحصل الفيض، لأن الثور لا يُحلب منه لبن، والعاقر لا تلد ولدًا.", "bait.024": "الصفات الأساسية للشيخ الكامل", "bait.025": "وينبغي أن يُعلم أنه لا بد أن تتوافر في الشيخ الكامل الصفات الخمس الآتية.", "bait.026": "يقول سلطان العارفين الشيخ أبو يزيد البسطامي رحمه الله:", "bait.027": "<b class=\"az-n\">١.</b> أن يكون الشيخ حسن الخلق.", "bait.028": "<b class=\"az-n\">٢.</b> أن يكون سخيًّا.", "bait.029": "<b class=\"az-n\">٣.</b> أن يكون متواضعًا.", "bait.030": "يقول شيخنا شمس الکونین خواجہ عبدالخالق رحمه الله:", "bait.031": "<b class=\"az-n\">٤.</b> أن يكون الشيخ ذا خلقٍ عظيم حتى تُحلّ مشكلات المريد بسهولة.", "bait.032": "<b class=\"az-n\">٥.</b> أن يُجري الشيخ عند البيعة ذكر اسم الذات من كل شعرةٍ في جسد المريد.", "mamulat.001": "ختم الخواجكان النقشبندية", "mamulat.002": "أصدرها مظہرِ جمالِ مصطفائی خواجۂ خواجگان، حامئ بیوگان، دستگیرِ یتامیٰ، فاتحِ قادیانیت، قطب الاقطاب، شمس الکونین ابوسعد محمد عبدالخالق نقشبندی رحمه الله", "mamulat.003": "ملاحظة: اقرأ البسملة الشريفة مرةً واحدة قبل كل وِردٍ ولا بد.", "mamulat.004": "(أطلب المغفرة من الله الذي لا معبود سواه، الحيّ القيّوم، وإليه أرجع تائبًا).", "mamulat.005": "سورة الفاتحة <span class=\"kk-c\">٧ مرات</span>", "mamulat.006": "الصلاة الخالقية (درودِ خالقیہ)", "mamulat.007": "(اللهم صلِّ بعدد معلوماتك كلها على سيدنا محمد ﷺ وعلى آل سيدنا محمد ﷺ وأصحابه).", "mamulat.008": "سورة ألم نشرح <span class=\"kk-c\">٧٩ مرة</span>", "mamulat.009": "سورة الإخلاص مع البسملة الشريفة <span class=\"kk-c\">١٠٠٠ مرة</span>", "mamulat.010": "سورة الفاتحة <span class=\"kk-c\">٧ مرات</span>", "mamulat.011": "اقرأ جميع الكلمات الآتية كلًّا منها مئة مرة:", "mamulat.012": "الصلاة الخالقية (درودِ خالقیہ)", "mamulat.013": "(القوة على اجتناب الذنوب والقدرة على فعل الخير إنما هما من الله)", "mamulat.014": "(لَا إِلَٰهَ إِلَّا أَنتَ سُبْحَانَكَ (عن الظلم) إِنِّي كُنتُ مِنَ الظَّالِمِينَ، أي إني أظلم نفسي).", "mamulat.015": "(يا حيّ يا قيّوم، أغِثني برحمتك يا غياث المستغيثين)", "mamulat.016": "(يا عزيز! اجعلني عزيزًا في أعين الخلق)", "mamulat.017": "(يا قاضي الحاجات)", "mamulat.018": "(يا رافع الدرجات)", "mamulat.019": "(يا دافع البليّات)", "mamulat.020": "(يا فاتح المغلقات)", "mamulat.021": "(يا شافي الأمراض)", "mamulat.022": "(يا مجيب الدعوات)", "mamulat.023": "(يا حلّال المشكلات)", "mamulat.024": "(يا مسبّب الأسباب)", "mamulat.025": "(يا مغني، يا من يُغني ويجعل غنيًّا)", "mamulat.026": "(يا غنيًّا عن كل شيء)", "mamulat.027": "(يا من يخلق بكثرة)", "mamulat.028": "(يا رزّاق، يا من يرزق ويُعطي بكثرة)", "mamulat.029": "(يا من يُنعم ويهب النِّعَم)", "mamulat.030": "(يا غنيّ! يا من يُغني عمّا سواه)", "mamulat.031": "(يا من يحبّ حبًّا لا حدّ له)", "mamulat.032": "(يا من يرحم كل أحدٍ رحمةً لا حدّ لها)", "mamulat.033": "(يا من هو في غاية الرأفة بخواصّه ومحبّيه)", "mamulat.034": "(يا من هو في غاية الكرم)", "mamulat.035": "(يا غفّار)", "mamulat.036": "(يا كثير العفو والستر)", "mamulat.037": "(يا كاشف الكُرَب وفاتح أبواب التيسير)", "mamulat.038": "(يا من يُعطي كل شيء)", "mamulat.039": "(يا مُعِزّ)", "mamulat.040": "(يا من يهب الرفعة)", "mamulat.041": "(يا باسط الرزق)", "mamulat.042": "(يا ذا الذات المنزّهة عن العيوب! يا واهب السلامة)", "mamulat.043": "(يا وكيلُ الحقيقي)", "mamulat.044": "(يا حفيظ! يا حافظ الخلق)", "mamulat.045": "(يا ربّ العالمين جميعًا)", "mamulat.046": "(يا مربّي العالمين جميعًا الحقيقي)", "mamulat.047": "(يا ربّ العالمين جميعًا الحقيقي)", "mamulat.048": "(برحمتك يا أرحم الراحمين)", "mamulat.049": "والآن اقرأ الختم الشريف الصغير:", "mamulat.050": "(اللهم إني أسألك المغفرة)", "mamulat.051": "(اللهم يا ربّي! إني أستغفرك من كل ذنب وأتوب إليك)", "mamulat.052": "سورة الفاتحة <span class=\"kk-c\">٧ مرات</span>", "mamulat.053": "الصلاة الخالقية (درودِ خالقیہ) <span class=\"kk-c\">١١ مرة</span>", "mamulat.054": "بوسيلة حضرة النبي الكريم ﷺ، أهدِ ثواب ذلك إلى جميع الأنبياء الكرام عليهم السلام، والخلفاء الراشدين، وأهل البيت الأطهار، والصحابة الكرام رضي الله عنهم، والمشايخ العظام.", "shajra.001": "شجرة الطريقة", "shajra.002": "مع أن مرشدينا حازوا الخلافة في السلاسل الأربع، فإنهم نشروا السلسلة العالية النقشبندية المجددية. ولذلك تُعرض أسماء أكابر هذه السلسلة العالية تبرّكًا وتعريفًا لعامة الناس.", "shajra.003": "رحمة للعالمين، خاتم النبيين، سيد المرسلين، حضرة محمد مصطفى ﷺ<small>الوفاة ١١هـ ـ المدفن: القبة الخضراء</small>", "shajra.004": "یارِ غار و مزار، افضل البشر بعد الانبیاء بالتحقیق، سیدنا ابوبکر صدیق رضي الله عنه<small>١٣هـ ـ القبة الخضراء، المدينة المنورة</small>", "shajra.005": "صحابیِ پاکباز، صاحبِ رسول اللہ ﷺ، حضرت سیدنا سلمان فارسی رضي الله عنه<small>٣٣هـ ـ المدائن، العراق</small>", "shajra.006": "حضرت سیدنا امام قاسم رحمه الله بن سیدنا محمد رحمه الله بن سیدنا ابوبکر صدیق رضي الله عنه<small>١٠٦هـ ـ المدينة المنورة</small>", "shajra.007": "امام الشریعت، ہادیِ طریقت حضرت سیدنا امام جعفر صادق رحمه الله<small>١٤٨هـ ـ جنة البقيع، قبة أهل البيت</small>", "shajra.008": "سلطان العارفین، غوثِ زمانی، حضرت شیخ بایزید بسطامی رحمه الله<small>٢٦١هـ ـ بسطام، إيران</small>", "shajra.009": "قطبِ ربانی، غوثِ زماں، خواجہ ابوالحسن خرقانی رحمه الله<small>٤٢٥هـ ـ خرقان قرب بسطام، إيران</small>", "shajra.010": "عارفِ ربانی، قطبِ زمانی، حضرت شیخ ابوالقاسم گرگانی رحمه الله<small>٤٥٠هـ ـ گرگان، إيران</small>", "shajra.011": "قطبِ صمدانی، حضرت شیخ بوعلی فارمدی رحمه الله<small>٤٧٧هـ ـ فارمد قرب طوس، خراسان، إيران</small>", "shajra.012": "رئیس الطریقت، غوثِ زماں، امامِ ربانی، خواجہ یوسف ہمدانی رحمه الله<small>٥٣٥هـ ـ مرو، إيران</small>", "shajra.013": "امام الطریقت خواجۂ جہاں خواجہ عبدالخالق غجدوانی رحمه الله<small>٥٧٥هـ ـ غجدوان قرب بخارى، أوزبكستان</small>", "shajra.014": "نورِ خدا، واقفِ معارفِ پیغمبری، خواجہ عارف ریوگری رحمه الله<small>٦١٦هـ ـ ريوگر قرب بخارى، أوزبكستان</small>", "shajra.015": "خواجۂ خواجگاں، قطبِ جہاں، حضرت خواجہ محمود انجیر فغنوی رحمه الله<small>٧١٥هـ ـ انجير فغنه قرب بخارى</small>", "shajra.016": "قطبِ زماں، مجددِ دوراں، حضرت خواجہ عزیزان علی رامیتنی رحمه الله<small>٧١٨هـ ـ خوارزم، أوزبكستان</small>", "shajra.017": "بابِ الطریقت، آفتابِ حقیقت حضرت خواجہ بابا محمد سماسی رحمه الله<small>٧٥٥هـ ـ سماس قرب بخارى</small>", "shajra.018": "عارفِ باکمال، صاحبِ وجد و حال، شمس الدین سید امیر کلال رحمه الله<small>٧٧٢هـ ـ سوخار، بخارى</small>", "shajra.019": "امام الطریقت پیرِ پیراں خواجۂ خواجگاں خواجہ بہاؤالدین نقشبند رحمه الله<small>٧٩١هـ ـ قصر عارفان، بخارى</small>", "shajra.020": "امام العارفین، قطبِ ارشاد حضرت خواجہ علاؤالدین عطار رحمه الله<small>٨٠٢هـ ـ چغانيان قرب بخارى</small>", "shajra.021": "شمس الہدایت، عارفِ ربانی، حضرت مولانا محمد یعقوب چرخی رحمه الله<small>٨٥١هـ ـ ما وراء النهر، طاجيكستان</small>", "shajra.022": "مرشدِ عارف، خواجہ ناصرالدین عبیداللہ احرار رحمه الله<small>٨٩٥هـ ـ سمرقند، أوزبكستان</small>", "shajra.023": "فیضِ الٰہی، یکتائے زمانہ، حضرت مولانا خواجہ محمد زاہد وخشی رحمه الله<small>٩٣٦هـ ـ وخش، بلخ</small>", "shajra.024": "مستِ عشق، حضرت مولانا خواجہ درویش محمد امکنگی رحمه الله<small>٩٧٠هـ ـ ما وراء النهر</small>", "shajra.025": "مرکزِ دائرۂ قطبیت، دربانِ رسول مولانا شاہ محمد خواجگی امکنگی رحمه الله<small>١٠٠٨هـ ـ امكنه، بخارى</small>", "shajra.026": "فخرِ اسلام، نقشبندِ وقت، قطبِ زماں، خواجہ محمد باقی باللہ بیرنگ رحمه الله<small>١٠١٢هـ ـ دلهي، الهند</small>", "shajra.027": "قیومِ اوّل، امامِ ربانی، مجدد الفِ ثانی، شیخ احمد فاروقی سرہندیؒ<small>١٠٣٤هـ ـ سرهند، الهند</small>", "shajra.028": "قیومِ ثانی، عروۃ الوثقیٰ خواجہ محمد معصوم رحمه الله<small>نجل مجدد الألف الثاني رحمه الله ـ ١٠٧٩هـ ـ سرهند الشريفة</small>", "shajra.029": "قاطعِ بدعت، محتسبِ اُمت شیخ سیف الدین رحمه الله<small>نجل قیومِ ثانی رحمه الله ـ ١٠٩٦هـ ـ سرهند الشريفة</small>", "shajra.030": "کشف الدجیٰ حضرت حافظ محمد محسن رحمه الله<small>خليفة خواجہ محمد معصوم رحمه الله ـ ١١٤٧هـ ـ دلهي</small>", "shajra.031": "حضرت سید نور محمد بدایونی رحمه الله<small>خليفة شیخ سیف الدین رحمه الله ـ ١١٣٥هـ ـ دلهي</small>", "shajra.032": "قطبِ زماں خواجہ محمد عابد سنامی رحمه الله<small>خليفة عبدالاحد سرہندی مجددی قادری رحمه الله ـ ١١٦٠هـ ـ دلهي</small>", "shajra.033": "قیومِ زماں، قطبِ جہاں، شمس الدین حبیب اللہ مرزا مظہر جانِ جاناں شہید رحمه الله<small>١١٩٥هـ ـ دلهي</small>", "shajra.034": "مجددِ دوراں، قیومِ زماں حضرت شاہ عبداللہ غلام علی دہلوی رحمه الله<small>١٢٤٠هـ ـ دلهي</small>", "shajra.035": "شیخ المشائخ، قیومِ زماں، حضرت شاہ ابوسعید فاروقی مجددی رحمه الله<small>١٢٥٠هـ ـ دلهي</small>", "shajra.036": "شمس الاولیاء، حضرت مولانا بابا محمد شریف قندھاری رحمه الله<small>١٢٦٠هـ ـ سرهند الشريفة</small>", "shajra.037": "سلطان الفقراء، حضرت حاجی محمود جالندھری رحمه الله<small>١٣٠٦هـ ـ جالندھر الشريفة، الهند</small>", "shajra.038": "شمس العرفان خواجہ قادر بخش رحمه الله<small>١٣٠٦هـ ـ کوٹ عبدالخالق جہانخیل، مديرية ہوشیارپور، الهند</small>", "shajra.039": "شمس الکونین خواجہ محمد عبدالخالق نقشبندی رحمه الله<small>١٩٣١م ـ کوٹ عبدالخالق جہانخیل، مديرية ہوشیارپور، الهند</small>", "shajra.040": "شمس العارفین سائیں عبدالرزاق خالقی نقشبندی رحمه الله<small>١٩٨٢م ـ دیپالپور شریف، مديرية اوکاڑہ</small>", "shajra.041": "امام الذاکرین حضور سائیں محمد عظیم اللہ رزاقی نقشبندی رحمه الله<small>٢٠١٣م ـ عظیم نگر شریف، مديرية بہاولنگر</small>", "shajra.042": "الشجرة الشريفة (منظومة)", "shajra.043": "يُؤكَّد تأكيدًا شديدًا على قراءة هذه الشجرة الطيبة بغاية الأدب وعلى وضوء. وعند القراءة أحضِر قلبك ووجّه انتباهك إلى درسك، وحافظ على صحة نسبتك الروحية، واطلب الفيض من المشايخ العظام. إن هذه الشجرة الطيبة محبوبة مقبولة عند حضرة سيد العالم محمد مصطفى ﷺ. وقد قبل النبي الكريم الرؤوف الرحيم ﷺ تواضع خادم خدّامه هذا، فأخبر الفقير في المنام أن من قرأ هذه الشجرة الطيبة بإخلاص النية فإن مشكلته مهما كانت ستُحلّ لا محالة إن شاء الله العزيز ببركة الخواجگان النقشبندية. وبعد قراءة الشجرة الشريفة قدِّم طلبك بواسطة حضرة النبي الكريم ﷺ، وادعُ محلِّل المشكلات، مسبِّب الأسباب، إله العالمين، أن يحلّ المشكلات.", "shajra.044": "خُذ بيدي بوسيلة محمد مصطفى ﷺ،", "shajra.045": "وبوسيلة آله وأصحابه وجميع الأنبياء.", "shajra.046": "يا إلهي، ارزق قلبي ألم محبتك،", "shajra.047": "بوسيلة أبي بكر الصديق الأكبر رضي الله عنه الصافي.", "shajra.048": "يا ربّي، اجعلني محترقًا في عشقك،", "shajra.049": "بوسيلة الصحابي سلمان الفارسي رضي الله عنه ذي الحياء.", "shajra.050": "لتبتعد عن قلبي كل خواطري بما سوى الله،", "shajra.051": "بوسيلة ذلك الإمام القاسم رحمه الله، شيخ الهدى.", "shajra.052": "يا إلهي، احفظني من شرّ النفس الكافرة،", "shajra.053": "بوسيلة جعفر الصادق رحمه الله، إمام الأتقياء.", "shajra.054": "يا إلهي، بصِّرني بمكر الشيطان،", "shajra.055": "بوسيلة ذلك الشيخ بایزید رحمه الله، الهادي المرشد.", "shajra.056": "ألّا أغفل لحظةً واحدة عن ذكرك،", "shajra.057": "بوسيلة الخواجه أبي الحسن رحمه الله، تاج الأولياء.", "shajra.058": "يا ربّ، أفنِني في ذاتك المطلقة،", "shajra.059": "بوسيلة ذلك الشاه أبي القاسم رحمه الله، صاحب اللواء.", "shajra.060": "يا ربّي، لا تجعلني غيرًا عن عين الذات المطلقة،", "shajra.061": "بوسيلة أبي علي رحمه الله، الشيخ والمرشد الوفيّ.", "shajra.062": "أزِل الغيرية عن القلب، وامنحني الحضور الدائم،", "shajra.063": "بوسيلة الخواجه يوسف رحمه الله، الشاه مستجاب الدعاء.", "shajra.064": "يا ربّ، لتنتقل روحي من الصورة (النقل) فتندمج في الأصل،", "shajra.065": "بوسيلة عبدالخالق الغجدواني رحمه الله، شفيع المخطئين.", "shajra.066": "امنحني معرفة النفس حتى أعرف الأصل،", "shajra.067": "بوسيلة ذلك محمد عارف رحمه الله، نور الله.", "shajra.068": "اجمع دائرة العشّاق بالمعشوق،", "shajra.069": "بوسيلة الخواجه محمود انجیر رحمه الله، صاحب الغنى.", "shajra.070": "ليسترح هذا الغريب في وصلك في كل لحظة،", "shajra.071": "بوسيلة الشاه عزیزان علي المرتضى رحمه الله.", "shajra.072": "اعفُ عن جميع خطاياي بنظرة الرحمة،", "shajra.073": "بوسيلة الخواجه بابا محمد رحمه الله، صاحب الأدب.", "shajra.074": "يا إلهي! اعدُدني في أمة أحمد ﷺ،", "shajra.075": "بوسيلة السيد میر کلال رحمه الله، صاحب الرضا.", "shajra.076": "ثبّتني مستقيمًا على الشريعة والطريقة،", "shajra.077": "بوسيلة الشاه بهاء الدين رحمه الله، الخواجه المقتدى.", "shajra.078": "امنحني الاستقامة الدائمة على الصراط المستقيم،", "shajra.079": "بوسيلة الشاه علاء الدين العطار رحمه الله، صاحب الضياء.", "shajra.080": "يا ربّي، ارزقني محبة الشيخ،", "shajra.081": "بوسيلة الخواجه يعقوب الچرخي رحمه الله، البريء من الرياء.", "shajra.082": "يا ربّ، اجعلني مقبولًا في نظر المشايخ الكرام،", "shajra.083": "بوسيلة ذلك عبيدالله الأحرار رحمه الله، صاحب السخاء.", "shajra.084": "أسكِن في قلبي عشق شيخي،", "shajra.085": "بوسيلة الخواجه زاهد محمد رحمه الله، المجتبى.", "shajra.086": "يا ربّ، ليبقَ بالي متوجهًا في كل لحظة إلى نصائح المشايخ،", "shajra.087": "بوسيلة الخواجه درويش محمد رحمه الله، آسر القلوب.", "shajra.088": "يا ربّي الكريم، امنح قلبي التوكّل،", "shajra.089": "بوسيلة الشاه محمد الخواجگي رحمه الله، ذي العلاء.", "shajra.090": "لا تجعلني حزينًا في الدنيا أبدًا،", "shajra.091": "بوسيلة ذلك محمد باقي بالله رحمه الله، صاحب البقاء.", "shajra.092": "يا إلهي، لا تجعلني محتاجًا إلى غيرك،", "shajra.093": "بوسيلة ذلك المجدد صاحب رحمه الله، بدر الدجى.", "shajra.094": "حين يحين وقت النزع لتكن كلمتك على لساني،", "shajra.095": "بوسيلة حضرة الخواجه معصوم رحمه الله، بحقّ الكبرياء.", "shajra.096": "احفظني في ذلك الوقت من شرّ الشيطان،", "shajra.097": "بوسيلة الشيخ سيف الدين رحمه الله، عاشق المصطفى ﷺ.", "shajra.098": "نجِّني بفضلك من سكرات الموت،", "shajra.099": "بوسيلة ذلك محمد عابد رحمه الله، كهف الورى.", "shajra.100": "يا إلهي، بفضلك ليكن قبري منيرًا،", "shajra.101": "بوسيلة الشاه محمد محسن رحمه الله، كاشف الدجى.", "shajra.102": "لا تكن عليّ شدة القبر ولا اضطراب من الملَك،", "shajra.103": "بوسيلة السيد نور محمد رحمه الله، الحسن الطلعة.", "shajra.104": "حين أمشي على الصراط ليكن العبور يسيرًا،", "shajra.105": "بوسيلة الخواجه میرزا جان جاناں رحمه الله، روحِنا.", "shajra.106": "يا ربّ، امنحني الأمان حين تشتدّ شمسك (يوم القيامة)،", "shajra.107": "بوسيلة ذلك غلام علي شاه رحمه الله، شمس الضحى.", "shajra.108": "يا إلهي، لتكن كفة الحسنات في الميزان راجحة،", "shajra.109": "بوسيلة أبي سعيد رحمه الله، هادي الأصفياء.", "shajra.110": "يا خالق العالم، لا يكن في تلك اللحظة أيّ اضطراب،", "shajra.111": "بوسيلة ذلك محمد شريف رحمه الله، الفادي بروحه.", "shajra.112": "يا ربّي العليم، ليكن مروري بين العشّاق،", "shajra.113": "بوسيلة الحاجي محمود الحافظ رحمه الله، شارح الصدور.", "shajra.114": "يا ربّ، لأكن يوم الجزاء تحت ظلّ شيخي،", "shajra.115": "بوسيلة الخواجه قادر بخش رحمه الله، ظلّ الهُما (طائر السعادة).", "shajra.116": "إن القلب يتألّم من حُمّى الفراق، فامنحه الدواء،", "shajra.117": "بوسيلة شمس العرفان رحمه الله، دواء القلب المحترق.", "shajra.118": "يا ربّي، ليكن وصل المحبوب نصيبي في كل لحظة،", "shajra.119": "بوسيلة خواجه جميع الخواجگان رحمه الله، رفيع الثناء.", "shajra.120": "أنا فقير الحال، فانظر إليّ يا ربّ نظرة رحمة،", "shajra.121": "بوسيلة المرشد المحبوب، مظهر شأن المصطفى ﷺ،", "shajra.122": "أعني قبلة روحي، خواجه العالم وملاذه،", "shajra.123": "بوسيلة شمس الکونین عبدالخالق رحمه الله، المقتدى.", "shajra.124": "يا إلهي، اجعلني موفَّقًا مكرَّمًا في الدين والدنيا،", "shajra.125": "بوسيلة سائیں الحبيب رحمه الله، الخواجه المقتدى.", "shajra.126": "غوث الزمان، قطب العالم، المرشد المنير الضمير،", "shajra.127": "بوسيلة سائیں عبدالرزاق رحمه الله، ذلك إمام الأولياء.", "shajra.128": "يا ربّي الكريم، املأ ذيل رجائي،", "shajra.129": "بوسيلة الشيخ الكامل الذي هو صورة ظلّ الإله.", "shajra.130": "زيّن قلبي ونظري بنور الإيمان،", "shajra.131": "بوسيلة الشاه محمد عظیم اللہ رحمه الله، ذلك نور الله.", "shajra.132": "مَن سواك؟ ولمن أشكو ألم قلبي؟", "shajra.133": "أنت وحدك قاضي الحاجات لكل مطلب.", "shajra.134": "يا الله، إني أواجه مئات الصعاب،", "shajra.135": "فيسِّرها بحقّ شأن كبريائك.", "shajra.136": "وإن كنتُ سيّئًا فأنا عبدك يا ربّي عزّ وجلّ،", "shajra.137": "ولا بد لي، أنا المسكين، من رحمتك.", "shajra.138": "يا إلهي، اجعل أولادي ذوي حظٍّ ونصيب،", "shajra.139": "بوسيلة جود الأنبياء والأولياء وعطائهم.", "shajra.140": "امنح الأصدقاء والأهل والأقارب المحبة،", "shajra.141": "بوسيلة آل النبي المقتدى ﷺ والحرمين.", "shajra.142": "يا إلهي، تقبّل دعاء عبدك العاصي،", "shajra.143": "بوسيلة ذلك الجناب، شفيع يوم الجزاء ﷺ.", "azkar.001": "الأذكار المسنونة", "azkar.002": "الأذكار المسنونة بعد صلاتي الفجر والمغرب", "azkar.003": "<p class=\"kk-ar\" lang=\"ar\">وَسَبِّحُوْهُ بُكْرَةً وَّاَصِيْلًا</p><p class=\"kk-ur\">وَسَبِّحُوهُ بُكْرَةً وَأَصِيلًا (سورة الأحزاب: ۴۲)</p>", "azkar.004": "ملاحظة: كان إمامنا الرباني مجدد الألف الثاني رحمه الله يقرأ أذكار الصباح والمساء المسنونة دائمًا.", "azkar.005": "(لا معبود إلا الله تعالى، وحده لا شريك له، له الملك وله الحمد، وهو على كل شيء قدير).", "azkar.006": "اللهم أجِرني من النار.", "azkar.007": "حسبي الله، لا معبود سواه، عليه توكلت، وهو ربّ العرش العظيم.", "azkar.008": "توكّلت على الحيّ الذي لا يموت.", "azkar.009": "(صحيح مسلم)", "azkar.010": "٦. سورة الإخلاص والمعوذتان مع التسمية <span class=\"kk-c\">٣ مرات</span>", "azkar.011": "(أبو داود)", "azkar.012": "رضيتُ بالله تعالى ربًّا، وبالإسلام دينًا، وبسيدنا حضرة محمد ﷺ نبيًّا ورسولًا.", "azkar.013": "(جامع الترمذي)", "azkar.014": "باسم الله تعالى الذي لا يضرّ مع اسمه شيءٌ في الأرض ولا في السماء، وهو السميع العليم.", "azkar.015": "(الترمذي)", "azkar.016": "اللهم عافني في بدني، اللهم عافني في سمعي، اللهم عافني في بصري، لا معبود إلا أنت.", "azkar.017": "(صحيح مسلم)", "azkar.018": "أعوذ بكلمات الله التامّات الكاملة من شرّ ما خلق.", "azkar.019": "(صحيح مسلم)", "azkar.020": "الأذكار المسنونة بعد الصلوات الخمس", "azkar.021": "<p class=\"kk-ar\" lang=\"ar\">فَاِذَا قَضَيْتُمُ الصَّلٰوةَ فَاذْكُرُوا اللّٰهَ قِيٰمًا وَّقُعُوْدًا وَّعَلٰى جُنُوْبِكُمْ</p><p class=\"kk-ur\">فَإِذَا قَضَيْتُمُ الصَّلَاةَ فَاذْكُرُوا اللَّهَ قِيَامًا وَقُعُودًا وَعَلَىٰ جُنُوبِكُمْ (سورة النساء: ۱۰۳)</p>", "azkar.022": "<p class=\"kk-ar\" lang=\"ar\">فَسَبِّحْهُ وَاَدْبَارَ السُّجُوْدِ</p><p class=\"kk-ur\">وسبِّحه بعد الصلوات أيضًا (ترجمة المعنى) (سورة ق: ۴۰)</p>", "azkar.023": "ملاحظة: كان إمامنا الرباني مجدد الألف الثاني رحمه الله يقرأ الأدعية المسنونة بعد كل صلاة. وعند قراءة الكلمات راعِ الترتيل والتجويد والمعاني، واقرأ التسمية قبل كل وِرد.", "azkar.024": "اللهم أنت السلام ومنك السلام، تباركتَ يا ذا الجلال والإكرام.", "azkar.025": "(صحيح مسلم)", "azkar.026": "٣. آية الكرسي", "azkar.027": "(سلسلة الأحاديث الصحيحة)", "azkar.028": "يا مقلّب القلوب! ثبّت قلبي على دينك وطاعتك.", "azkar.029": "(الترمذي)", "azkar.030": "رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِن لَّدُنكَ رَحْمَةً ۚ إِنَّكَ أَنتَ الْوَهَّابُ", "azkar.031": "(ابن ماجه) (سورة آل عمران: ۸)", "azkar.032": "اللهم أعنّي على ذكرك وشكرك وحسن عبادتك.", "azkar.033": "(أبو داود)", "azkar.034": "يا حيّ يا قيّوم! لا معبود إلا أنت، أسألك أن تُحيي قلبي إلى الأبد بنور معرفتك، يا ذا الجلال والإكرام! سبحانك.", "azkar.035": "(كنز العمال)", "azkar.036": "٨. تسبيح فاطمة", "azkar.037": "سبحان الله ٣٣ مرة، والحمد لله ٣٣ مرة، والله أكبر ٣٣ مرة، وكلمة التوحيد مرة واحدة.", "azkar.038": "(صحيح مسلم)", "azkar.039": "(الترمذي)", "azkar.040": "١٠. كلمة التمجيد", "azkar.041": "١١. القلاقل الثلاث الشريفة (الإخلاص والفلق والناس)", "azkar.042": "١١. سورة الإخلاص <span class=\"kk-c\">١٠ مرات</span>", "azkar.043": "(مسند أحمد)", "azkar.044": "الختم الصغير للخواجگان", "azkar.045": "اجعل من عادتك قراءة الختم الصغير للخواجگان الآتي بعد صلاة الفجر وبعد صلاة العصر.", "azkar.046": "١. أستغفر الله <span class=\"kk-c\">٢٦ مرة</span>", "azkar.047": "٢. سورة الفاتحة <span class=\"kk-c\">٧ مرات</span>", "azkar.048": "٣. الصلاة على النبي ﷺ <span class=\"kk-c\">١١ مرة</span>", "azkar.049": "أدعية إضافية مسنونة للصلاة", "azkar.050": "ملاحظة: يقول عروة الوثقى خواجہ محمد معصوم سرہندی رحمه الله: إن قراءة أدعية الاستفتاح المأثورة سوى الثناء، وكذلك أدعية الركوع والسجود سوى التسبيحات، وأدعية القومة والجلسة المذكورة في الأحاديث المباركة، في التهجد وسائر النوافل أمرٌ حسنٌ جدًّا، وفي القعدة الأخيرة بعد الصلاة على النبي ﷺ تُقرأ الأدعية القرآنية أو الأدعية المأثورة المسنونة. كما في الحديث الشريف في صحيح البخاري: «ثم ليتخيّر من الدعاء أعجبه إليه». (اذکارِ نبویہ)", "azkar.051": "الله أكبر كبيرًا، والحمد لله كثيرًا، وأسبّح الله بكرةً وأصيلًا. يروي حضرة جبير بن مطعم رضي الله عنه أنه رأى النبي ﷺ يصلّي صلاةً، فقرأ ﷺ هذه الكلمات في بداية الصلاة.", "azkar.052": "(سنن أبي داود)", "azkar.053": "سبّوحٌ قدّوس، ربّ الملائكة والروح. قراءة هذه الكلمات في الركوع والسجود سنة. قال النبي ﷺ: أقرب ما يكون العبد من ربه وهو ساجد، فأكثروا الدعاء في السجود.", "azkar.054": "(صحيح مسلم)", "azkar.055": "ملاحظة: كان إمامنا الرباني مجدد الألف الثاني رحمه الله يقرأ التسبيحات في الركوع والسجود في أوقات الفراغ خمسًا أو سبعًا أو تسعًا أو إحدى عشرة مرة، وكان يقول: أستحيي أن أكتفي بثلاث تسبيحات فقط مع القدرة وفي حال الفراغ. (حضرات القدس)", "azkar.056": "ربّنا لك الحمد حمدًا كثيرًا طيبًا مباركًا فيه، كما يحبّ ربّنا ويرضى. قراءة هذه الكلمات في القومة، أي بعد الرفع من الركوع، سنة، ولا سيما في صلاة النافلة.", "azkar.057": "(البخاري)", "azkar.058": "اللهم اغفر لي وارحمني واهدني وارزقني وارفعني واجبرني وعافني. قراءة هذه الكلمات في الجلسة بين السجدتين سنة، ولا سيما في صلاة النافلة.", "azkar.059": "(سنن أبي داود، الترمذي)", "azkar.060": "الأذكار المسنونة عند النوم", "azkar.061": "يقول الله تعالى في سورة الزمر: اللَّهُ يَتَوَفَّى الْأَنفُسَ حِينَ مَوْتِهَا وَالَّتِي لَمْ تَمُتْ فِي مَنَامِهَا (۴۲)", "azkar.062": "<p class=\"kk-ar\" lang=\"ar\">وَسَبِّحْهُ لَيْلًا طَوِيْلًا</p><p class=\"kk-ur\">وقال تعالى في سورة الدهر: وَسَبِّحْهُ لَيْلًا طَوِيلًا (۲۶)</p>", "azkar.063": "قال النبي الكريم ﷺ: إن أناسًا في الدنيا يذكرون الله تعالى على الفُرُش الليّنة، يُدخلهم الله تعالى الجنة العُليا. (مصنف أبي يوسف). ومن اضطجع على فراشه أو جلس في مجلسٍ لا يذكر الله تعالى فيه كان ذلك عليه حسرةً يوم القيامة. (أبو داود)", "azkar.064": "ملاحظة: كان إمامنا الرباني رحمه الله يقرأ عند النوم السور والآيات والتسبيحات والأدعية المأثورة.", "azkar.065": "قال النبي الكريم ﷺ لسيدنا علي المرتضى رضي الله عنه: يا علي! نَم بعد أن تفعل خمسة أشياء:", "azkar.066": "١. سورة الفاتحة <span class=\"kk-c\">٤ مرات</span>", "azkar.067": "اقرأها أربع مرات ثم نَم، فذلك يعدل التصدّق بأربعة آلاف دينار.", "azkar.068": "٢. سورة الإخلاص <span class=\"kk-c\">٣ مرات</span>", "azkar.069": "اقرأها ثلاث مرات ثم نَم، فذلك يعدل ختم القرآن المجيد مرة واحدة.", "azkar.070": "اقرأه عشر مرات ثم نَم، فأجره يعدل الإصلاح بين متخاصمَين.", "azkar.071": "٤. الصلاة على النبي ﷺ <span class=\"kk-c\">١٠ مرات</span>", "azkar.072": "اقرأها عشر مرات ثم نَم، فذلك يعدل أداء ثمن الجنة.", "azkar.073": "٥. كلمة التمجيد <span class=\"kk-c\">٤ مرات</span>", "azkar.074": "اقرأها أربع مرات ثم نَم، فذلك يعدل أداء حجة.", "azkar.075": "٦. سورة الكافرون <span class=\"kk-c\">مرة واحدة</span>", "azkar.076": "يقول حضرة نوفل رضي الله عنه: قال لي النبي الكريم ﷺ: اقرأ سورة الكافرون ثم نَم، فإنها براءة من الشرك.", "azkar.077": "(أبو داود)", "azkar.078": "٧. القلاقل الثلاث الشريفة (الإخلاص والفلق والناس) <span class=\"kk-c\">٣ مرات</span>", "azkar.079": "تقول أم المؤمنين عائشة الصديقة رضي الله عنها: كان النبي الكريم ﷺ إذا أوى إلى فراشه جمع كفّيه ثم قرأ سورة الإخلاص والفلق والناس ونفث فيهما، ثم مسح بهما ما استطاع من جسده الأقدس، يبدأ بهما على رأسه ووجهه، يفعل ذلك ثلاث مرات.", "azkar.080": "(صحيح البخاري)", "azkar.081": "قال النبي ﷺ: من قرأ هذا الاستغفار حين يأوي إلى فراشه ثلاث مرات غُفرت ذنوبه وإن كانت مثل زبد البحر، وإن كانت عدد ورق الشجر، وإن كانت عدد رمل التلال، وإن كانت عدد أيام الدنيا.", "azkar.082": "(الترمذي)", "azkar.083": "٩. آية الكرسي", "azkar.084": "قال النبي ﷺ: من قرأ آية الكرسي عند النوم وُكِّل به ملَكٌ يحفظه، ولا يقربه شيطان حتى يصبح. (البخاري) ومن قرأها مضطجعًا على فراشه حفظ الله تعالى عدة بيوت من حوله.", "azkar.085": "١٠. البسملة الشريفة <span class=\"kk-c\">٢١ مرة</span>", "azkar.086": "قال النبي الكريم ﷺ: من قرأ التسمية قبل النوم ٢١ مرة كان محفوظًا من السرقة ومن تأثيرات الشيطان ومن موت الفجأة.", "azkar.087": "١١. تسبيح فاطمة", "azkar.088": "(متفق عليه)", "azkar.089": "١٢. دعاء النوم", "azkar.090": "اللهم باسمك أموت وباسمك أحيا.", "azkar.091": "(متفق عليه)", "azkar.092": "١٣. الآيتان الأخيرتان من سورة البقرة", "azkar.093": "الأذكار المسنونة لليلة الجمعة ويوم الجمعة", "azkar.094": "ملاحظة: كان إمامنا الرباني مجدد الألف الثاني رحمه الله يُكثر من إرسال أنواع الصلوات الشريفة إلى حضرة النبي الكريم ﷺ، ولا سيما في ليلة الجمعة ويومها، وليلة الاثنين ويومه. وفي أواخر حياته كان يصلّي على النبي ﷺ ألف مرة ليلة الجمعة بعد حلقة الذكر مع المريدين.", "azkar.095": "١. الصلاة على النبي ﷺ ليلة الجمعة <span class=\"kk-c\">ألف مرة</span>", "azkar.096": "٢. الصلاة على النبي ﷺ بعد الجمعة <span class=\"kk-c\">ألف مرة</span>", "azkar.097": "أوصى الشيخ عبدالقادر الجيلاني رحمه الله في «غنية الطالبين» بقراءة هذه الصلاة الشريفة يوم الجمعة.", "azkar.098": "٣. الصلاة على النبي ﷺ بعد صلاة العصر <span class=\"kk-c\">٨٠ مرة</span>", "azkar.099": "عن سيدنا أبي هريرة رضي الله عنه أن النبي ﷺ قال: من صلّى العصر يوم الجمعة ثم قرأ هذه الصلاة الطاهرة ٨٠ مرة وهو جالس في مكانه غُفرت له ذنوب ثمانين سنة، وكُتب له في صحيفة أعماله ثواب عبادة ثمانين سنة.", "azkar.100": "(الديلمي، الإمام السخاوي)", "azkar.101": "٤. کیمیائے مشائخ (كيمياء المشايخ)", "azkar.102": "كتب الشيخ عبدالحق المحدّث الدهلوي رحمه الله وظيفةً مجرَّبة لمغفرة الذنوب ما تقدّم منها وما تأخّر سمّاها «كيمياء المشايخ»: وهي أن يقرأ بعد السلام من صلاة الجمعة، وهو على هيئة التشهد، سورة الفاتحة والقلاقل الثلاث الشريفة مع التسمية سبع مرات لكلٍّ منها. وفي الحديث الشريف أن قراءة هذه السور تُعيذ من الشيطان من هذه الجمعة إلى الجمعة التالية.", "azkar.103": "(کیمیائے سعادت)", "azkar.104": "ملاحظة: كان الإمام الرباني رحمه الله يقرأ بعد صلاة الجمعة سورة الفاتحة والقلاقل الثلاث مع التسمية سبع مرات لكلٍّ منها.", "azkar.105": "<p class=\"kk-ar\" lang=\"ar\">فَاِذَا قُضِيَتِ الصَّلٰوةُ فَانْتَشِرُوْا فِي الْاَرْضِ وَابْتَغُوْا مِنْ فَضْلِ اللّٰهِ</p><p class=\"kk-ur\">فَإِذَا قُضِيَتِ الصَّلَاةُ فَانتَشِرُوا فِي الْأَرْضِ وَابْتَغُوا مِن فَضْلِ اللَّهِ (سورة الجمعة: ۱۰)</p>", "azkar.106": "يقول حضرة أنس رضي الله عنه: ليس معنى هذه الآية البيع والشراء وكسب الدنيا، بل المراد بها طلب العلم، وزيارة الإخوان، وعيادة المرضى، واتّباع الجنائز، وكل ما كان من مثل هذه الأعمال الصالحة؛ لأن الله تعالى قال بعد ذلك في سورة الجمعة:", "azkar.107": "<p class=\"kk-ar\" lang=\"ar\">وَاذْكُرُوا اللّٰهَ كَثِيْرًا لَّعَلَّكُمْ تُفْلِحُوْنَ</p><p class=\"kk-ur\">وَاذْكُرُوا اللَّهَ كَثِيرًا لَّعَلَّكُمْ تُفْلِحُونَ</p>", "programs.001": "البرامج السنوية", "atiyat.001": "التبرعات", "atiyat.002": "لمن يرغب في دعم الخدمات الدينية والإصلاحية للحركة — تقبّل الله منكم.", "rabta.001": "اتصل بنا", "about.001": "عن التطبيق", "kutub.020": "خشية الله وعشق المصطفى ﷺ", "kutub.021": "<span>المؤلف:</span> مؤسس وقائد تحریک اتباعِ سنت پاکستان، شيخ الطريقة، شیرِ مجدد بدرالہدیٰ کرامت علی رزّاقی عظیمی نقشبندی <span class=\"lat\">(M.A, L.L.B)</span>", "kutub.022": "<span>بمساعدة:</span> المهندس شعیب عالم عظیمی مجددی (ماجستير في العلوم الإسلامية)، <span class=\"lat\">HOD</span> تخصص الكهرباء، المعهد الحكومي للتدريب الفني، لودھراں", "kutub.023": "عدد الصفحات: <span class=\"lat\">128</span>  • النشر: ديسمبر <span class=\"lat\">2019</span> (الطبعة الثانية)"};
